return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-06 01:48+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'وو ڪامرس','Go to Plugin Search' => 'پلگ ان ڳولا ڏانهن وڃو','Activate %s' => '%s کي چالو ڪريو','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s کي</strong> انسٽال ۽ چالو ڪرڻ لاءِ <strong>%2$s جي</strong> ضرورت آهي. <a href="%4$s">%3$s</a>','Enter your code here' => 'هتي پنهنجو ڪوڊ داخل ڪريو.','Add %s' => '%s شامل ڪريو','Remove' => 'هٽايو','Order number and receipt will be sent to this email address.' => 'آرڊر نمبر ۽ رسيد هن اي ميل ايڊريس تي موڪلي ويندي.','Apartment, unit, building, floor, etc.' => 'اپارٽمينٽ، يونٽ، عمارت، فرش، وغيره.','Shipping phone' => 'شپنگ فون','Only used for shipping-related questions.' => 'صرف شپنگ سان لاڳاپيل سوالن لاءِ استعمال ڪيو ويندو آهي.','Single step' => 'هڪ قدم','Click to go to the order summary' => 'آرڊر جي خلاصي ڏانهن وڃڻ لاءِ ڪلڪ ڪريو','Cart total:' => 'ڪارٽ جو ڪل:','Proceed to %s' => '%s تائين اڳتي وڌو','Proceed to contact' => 'رابطو ڪرڻ لاءِ اڳتي وڌو','Proceed to shipping' => 'شپنگ تي اڳتي وڌو','Proceed to billing' => 'بلنگ تي اڳتي وڌو','Proceed to payment' => 'ادائيگي لاءِ اڳتي وڌو','Shipping method' => 'پهچائڻ جو طريقو','Additional notes' => 'اضافي نوٽس','Payment method' => 'ادائيگي جو طريقو','Step %1$s of %2$s' => 'قدم %2$s مان %1$s','Change: %s' => 'تبديلي: %s','Not selected yet.' => 'اڃا تائين چونڊيل نه آهي.','Same as shipping address' => 'شپنگ ايڊريس وانگر ساڳيو','Same as billing address' => 'بلنگ ايڊريس وانگر ساڳيو','Order summary' => 'آرڊر جو خلاصو','Edit cart' => 'ڪارٽ ۾ ترميم ڪريو','Did you mean %s?' => 'ڇا توهان جو مطلب %s هو؟','Change email address to: {suggestion-value}' => 'اي ميل پتو هن ۾ تبديل ڪريو: {suggestion-value}','This is a required field.' => 'هي هڪ گهربل ميدان آهي.','This is not a valid email address.' => 'هي هڪ صحيح اي ميل پتو نه آهي.','This field does not match the related field value.' => 'هي فيلڊ لاڳاپيل فيلڊ ويليو سان نه ٿو ملي.','The CPF number "{cpf_number}" is invalid.' => 'سي پي ايف نمبر &quot;{cpf_number}&quot; غلط آهي.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ نمبر &quot;{cnpj_number}&quot; غلط آهي.','(Required)' => '(گهربل)','Checkout Header - Desktop' => 'چيڪ آئوٽ هيڊر - ڊيسڪ ٽاپ','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'وڏين اسڪرينن لاءِ چيڪ آئوٽ هيڊر تي ويجيٽس ڏيکاريو. صرف پلگ ان جي چيڪ آئوٽ هيڊر استعمال ڪرڻ تي ڏيکاريو ويندو.','Checkout Header - Mobile' => 'چيڪ آئوٽ هيڊر - موبائل','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'موبائل ڊوائيسز لاءِ چيڪ آئوٽ هيڊر هيٺان ويجيٽس ڏيکاريو. صرف پلگ ان جي چيڪ آئوٽ هيڊر استعمال ڪرڻ تي ڏيکاريو ويندو.','Checkout Sidebar' => 'چيڪ آئوٽ سائڊبار','Display widgets on the checkout sidebar after the order summary.' => 'آرڊر جي خلاصي کان پوءِ چيڪ آئوٽ سائڊبار تي ويجيٽس ڏيکاريو.','Checkout Order Summary' => 'چيڪ آئوٽ آرڊر جو خلاصو','Display widgets inside the order summary at the checkout page.' => 'چيڪ آئوٽ صفحي تي آرڊر خلاصي اندر ويجيٽس ڏيکاريو.','Checkout Below Place Order' => 'هيٺ چيڪ آئوٽ ڪريو آرڊر ڏيو','Display widgets below the place order button at the checkout page.' => 'چيڪ آئوٽ صفحي تي آرڊر بٽڻ جي هيٺان ويجيٽس ڏيکاريو.','Checkout Footer' => 'فوٽر چيڪ ڪريو','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'چيڪ آئوٽ فوٽر تي ويجيٽس ڏيکاريو. صرف پلگ ان جي چيڪ آئوٽ فوٽر استعمال ڪرڻ تي ڏيکاريو ويندو.','Classic' => 'ڪلاسيڪل','Boxed' => 'دٻيل','Split' => 'ورهايو','Minimalist' => 'گھٽ ۾ گھٽ','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'ڪوڊ راڪز پاران فلوئڊ چيڪ آئوٽ ۽ ڊليوري جي تاريخ پلگ ان','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p style=";text-align:right;direction:rtl">اسان کي خبر پئي ته توهان CodeRockz پاران WooCommerce (مفت ۽ PRO) لاءِ ڊليوري ۽ پڪ اپ تاريخ جو وقت پلگ ان استعمال ڪري رهيا آهيو. انهن پلگ ان سان انضمام کي Fluid Checkout PRO ڏانهن منتقل ڪيو ويو آهي.</p>','Upgrade to PRO' => 'پرو ۾ اپ گريڊ ڪريو','Fluid Checkout database updated successfully' => 'فلوئڊ چيڪ آئوٽ ڊيٽابيس ڪاميابي سان اپڊيٽ ڪيو ويو.','The database changes where applied successfully.' => 'جتي ڪاميابي سان لاڳو ڪيو ويو، ڊيٽابيس تبديل ٿي ويندو.','Dismiss' => 'رد ڪريو','Fluid Checkout database update' => 'فلوئڊ چيڪ آئوٽ ڊيٽابيس اپڊيٽ','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ڊيٽابيس ۾ ڪجھ تبديليون گھربل آھن. جيئن ڪنھن به اپڊيٽ سان، اسان توھان کي صلاح ڏيون ٿا ته <strong>اڳتي وڌڻ کان اڳ پنھنجي ويب سائيٽ جو مڪمل بيڪ اپ وٺو</strong> .','Update database' => 'ڊيٽابيس کي اپڊيٽ ڪريو','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'فلوئڊ چيڪ آئوٽ ڊوي بلڊر چيڪ آئوٽ لي آئوٽ سان مطابقت نٿو رکي.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p style=";text-align:right;direction:rtl">فلوئڊ چيڪ آئوٽ کي ڪم ڪرڻ لاءِ ڪلاسڪ WooCommerce شارٽ ڪوڊ تي ٻڌل چيڪ آئوٽ فارم جي ضرورت آهي. جڏهن چيڪ آئوٽ پيج جي ڏيک ۽ احساس کي ترتيب ڏيڻ لاءِ Divi Builder استعمال ڪيو ويندو آهي، ته چيڪ آئوٽ پيج جي هر حصي لاءِ ڪلاسڪ شارٽ ڪوڊز کي Divi Builder کان ڪسٽم ويجيٽس سان تبديل ڪيو ويندو آهي. اهي ڪسٽم ويجيٽس فلوئڊ چيڪ آئوٽ سان مطابقت نه رکندا آهن.</p><p style=";text-align:right;direction:rtl"> مھرباني ڪري پنھنجي چيڪ آئوٽ صفحي کي ايڊٽ ڪريو ۽ Divi Builder ويجيٽس کي ھڪ ٽيڪسٽ ويجيٽ سان تبديل ڪريو جنھن ۾ مختصر ڪوڊ <code>[woocommerce_checkout]</code> شامل آھي.</p>','Edit the checkout page' => 'چيڪ آئوٽ صفحي کي ايڊٽ ڪريو','Read the documentation.' => 'دستاويز پڙهو.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'فلوئڊ چيڪ آئوٽ استعمال ڪرڻ وقت جرمنائيزڊ پي آر او ملٽي اسٽيپ چيڪ آئوٽ فيچر کي غير فعال ڪرڻ جي ضرورت آهي.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'فلوئڊ چيڪ آئوٽ استعمال ڪرڻ وقت، جرمنائيزڊ پرو پلگ ان مان ملٽي اسٽيپ فيچر غير ضروري ٿي ويندو آهي ۽ <strong>نوان آرڊر پروسيس ڪرڻ دوران اهم غلطيون</strong> پيدا ڪري سگهي ٿو. مھرباني ڪري پلگ ان سيٽنگز ۾ جرمنائيزڊ پرو ملٽي اسٽيپ چيڪ آئوٽ فيچر کي غير فعال ڪريو.','Go to Germanized settings' => 'جرمنائيزڊ سيٽنگز ڏانهن وڃو','Thanks for choosing Fluid Checkout!' => 'فلوئڊ چيڪ آئوٽ چونڊڻ لاءِ مهرباني!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'توهان ڪافي عرصي کان پلگ ان استعمال ڪري رهيا آهيو. توهان کي هاڻي تائين اهو ڪيئن لڳو؟<br> مهرباني ڪري اسان کي هڪ تڪڙي ريٽنگ ڏيو، اسان هر موٽ جي تعريف ڪريون ٿا ۽ اهو اسان کي پلگ ان کي بهتر بڻائڻ جي حوصلا افزائي ڪري ٿو :)','Rate the plugin' => 'پلگ ان جي درجه بندي ڪريو','I need help!' => 'مونکي مدد گهرجي!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ڪواڊليئرز پاران WooCommerce Checkout Manager جون ڪجھ خاصيتون Fluid Checkout سان استعمال ڪرڻ وقت اميد مطابق ڪم نه ڪري سگھن ٿيون. وڌيڪ معلومات ۽ متبادل حلن لاءِ <a href="%s">اسان جا دستاويز</a> پڙهو.','Read documentation' => 'دستاويز پڙهو','Don\'t show this again' => 'هي ٻيهر نه ڏيکاريو.','Fluid Checkout PRO' => 'فلوئڊ چيڪ آئوٽ پرو','More design templates' => 'وڌيڪ ڊيزائن ٽيمپليٽ','Optimized cart page' => 'بهتر ڪيل ڪارٽ صفحو','Optimized order received / thank you page' => 'بهتر ڪيل آرڊر ملي ويو / مهرباني جو صفحو','Edit cart contents at checkout page' => 'چيڪ آئوٽ صفحي تي ڪارٽ جي مواد کي ايڊٽ ڪريو','Account matching / user matching' => 'اڪائونٽ ميچنگ / استعمال ڪندڙ ميچنگ','Trust symbols on the cart and thank you pages' => 'ڪارٽ ۽ شڪرگذاري جي صفحن تي اعتماد جا نشان','More positions for the coupon code on the checkout page' => 'چيڪ آئوٽ صفحي تي ڪوپن ڪوڊ لاءِ وڌيڪ پوزيشنون','International phone numbers' => 'بين الاقوامي فون نمبر','Gift messages and packing slips' => 'تحفي جا پيغام ۽ پيڪنگ سلپس','Local pickup and in-store collection' => 'مقامي پڪ اپ ۽ اسٽور ۾ گڏ ڪرڻ','EU-VAT Assistant' => 'EU-VAT اسسٽنٽ','I already have it – Hide this offer' => 'مون وٽ اڳ ۾ ئي آهي - هي آڇ لڪايو','Activated' => 'چالو ٿيل','Address book' => 'ايڊريس بڪ','Select an image' => 'هڪ تصوير چونڊيو','Cart layout' => 'ڪارٽ لي آئوٽ','Cart optimizations' => 'ڪارٽ جي اصلاح','Enable cart page optimizations' => 'ڪارٽ پيج جي اصلاح کي فعال ڪريو','Header and footer template' => 'هيڊر ۽ فوٽر ٽيمپليٽ','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ڪنٽرول ڪري ٿو ته ڇا خلفشار کان پاڪ صفحي جي هيڊر ۽ فوٽر کي استعمال ڪجي يا موجوده فعال ٿيم جي هيڊر ۽ فوٽر کي رکيو وڃي.','Distraction free header and footer' => 'خلفشار کان سواءِ هيڊر ۽ فوٽر','Theme\'s header and footer' => 'ٿيم جو هيڊر ۽ فوٽر','Cart elements' => 'ڪارٽ جا عنصر','Make the order summary stay visible on the cart page while scrolling' => 'آرڊر جو خلاصو اسڪرول ڪندي ڪارٽ پيج تي نظر اچي رهيو آهي.','Coupon codes' => 'ڪوپن ڪوڊ','Hidden' => 'لڪايو ويو','Before the cart items section' => 'ڪارٽ آئٽمز سيڪشن کان اڳ','Inside the cart items section' => 'ڪارٽ آئٽمز سيڪشن جي اندر','After the cart items section' => 'ڪارٽ آئٽمز سيڪشن کان پوءِ','Before the shipping section' => 'شپنگ سيڪشن کان اڳ','After the shipping section' => 'شپنگ سيڪشن کان پوءِ','Before the order summary' => 'آرڊر جي خلاصي کان اڳ','Inside the order summary' => 'آرڊر جي خلاصي اندر','Before the order totals' => 'آرڊر جي مجموعي کان اڳ','After the order totals' => 'آرڊر جي مجموعي کان پوءِ','After the order summary' => 'آرڊر جي خلاصي کان پوءِ','Shipping' => 'شپنگ','Select position where to display the shipping costs and calculator on the cart page.' => 'ڪارٽ واري صفحي تي شپنگ جي قيمتن ۽ ڪيلڪيوليٽر کي ڏيکارڻ لاءِ جڳهه چونڊيو.','Display as a cart section' => 'ڪارٽ سيڪشن طور ڏيکاريو','Cross-sells' => 'ڪراس سيلز','Select position where to display the cross-sells section on the cart page.' => 'ڪارٽ پيج تي ڪراس سيلز سيڪشن ڏيکارڻ لاءِ جڳهه چونڊيو.','Before the cart actions' => 'ڪارٽ جي ڪارروائي کان اڳ','After the cart actions' => 'ڪارٽ جي ڪارروائي کان پوءِ','Layout of cross-sell items on the cart page.' => 'ڪارٽ واري صفحي تي ڪراس سيل شين جو لي آئوٽ.','Optimized horizontal cross-sells layout' => 'بهتر ڪيل افقي ڪراس سيلز لي آئوٽ','Theme\'s cross-sells layout' => 'ٿيم جو ڪراس سيلز لي آئوٽ','Number of cross-sell items to display on the cart page' => 'ڪارٽ صفحي تي ڏيکارڻ لاءِ ڪراس سيل شين جو تعداد','Add widget areas to the cart page' => 'ڪارٽ پيج تي ويجيٽ ايريا شامل ڪريو','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'اهي ويجيٽ ايريا ڪارٽ پيج تي اعتماد جي علامتن ۽ اعتماد جي بيجز کي شامل ڪرڻ لاءِ استعمال ڪيا ويندا آهن.','Checkout' => 'چيڪ آئوٽ ڪريو','Checkout layout' => 'چيڪ آئوٽ لي آئوٽ','Design template' => 'ڊيزائن ٽيمپليٽ','Dark mode' => 'ڊارڪ موڊ','Enable dark mode' => 'ڊارڪ موڊ کي فعال ڪريو','Logo image' => 'لوگو جي تصوير','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'چيڪ آئوٽ پيج هيڊر تي ڏيکارڻ لاءِ هڪ تصوير چونڊيو. صرف ان وقت لاڳو ٿئي ٿو جڏهن خلفشار کان پاڪ هيڊر ۽ فوٽر استعمال ڪيو وڃي.','Header background color' => 'هيڊر پس منظر جو رنگ','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'چيڪ آئوٽ پيج هيڊر لاءِ پس منظر جو رنگ چونڊيو. صرف ان وقت لاڳو ٿئي ٿو جڏهن خلفشار کان پاڪ هيڊر ۽ فوٽر استعمال ڪيو وڃي.','HTML color value. ie: #f3f3f3' => 'HTML رنگ جي قيمت. يعني: #f3f3f3','Page background color' => 'صفحي جي پس منظر جو رنگ','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'چيڪ آئوٽ صفحي لاءِ پس منظر جو رنگ چونڊيو. رنگ <em>جسم جي</em> عنصر تي لاڳو ڪيو ويندو آهي.','Footer background color' => 'فوٽر پس منظر جو رنگ','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'چيڪ آئوٽ پيج فوٽر لاءِ پس منظر جو رنگ چونڊيو. صرف ان وقت لاڳو ٿئي ٿو جڏهن خلفشار کان پاڪ هيڊر ۽ فوٽر استعمال ڪيو وڃي.','Progress bar' => 'ترقي بار','Display the checkout progress bar when using multi-step checkout layout' => 'گھڻ-قدمي چيڪ آئوٽ لي آئوٽ استعمال ڪندي چيڪ آئوٽ پروگريس بار ڏيکاريو','Make the checkout progress bar stay visible while scrolling' => 'اسڪرولنگ دوران چيڪ آئوٽ پروگريس بار کي نظر ايندڙ بڻايو','Express checkout' => 'ايڪسپريس چيڪ آئوٽ','Enable the express checkout section' => 'ايڪسپريس چيڪ آئوٽ سيڪشن کي فعال ڪريو','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'جڏهن سپورٽ ٿيل ادائيگي گيٽ ويز ۾ هي خصوصيت فعال هوندي آهي ته چيڪ آئوٽ تي ايڪسپريس چيڪ آئوٽ سيڪشن ڏيکاري ٿو.','Display express checkout buttons in one line for larger screens' => 'وڏين اسڪرينن لاءِ ايڪسپريس چيڪ آئوٽ بٽڻن کي هڪ لائن ۾ ڏيکاريو','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'هڪ مطابقت رکندڙ ايڪسپريس چيڪ آئوٽ ادائيگي گيٽ وي سان ادائيگي ڪرڻ وقت اضافي چيڪ آئوٽ گهربل فيلڊز کي نظرانداز ڪريو.','Make the order summary stay visible while scrolling' => 'آرڊر جي خلاصي کي اسڪرول ڪندي نظر اچڻ ڏيو','Choose a background color for the order summary section.' => 'آرڊر خلاصو سيڪشن لاءِ پس منظر جو رنگ چونڊيو.','Highlight the order totals row in the order summary table' => 'آرڊر جي خلاصي جي جدول ۾ آرڊر جي مجموعي قطار کي نمايان ڪريو.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'جڏهن آرڊر سمري سيڪشن ۾ نمايان ٿيل پس منظر جو رنگ نه هجي ته تمام گهڻو ڪارآمد آهي. فلوئڊ چيڪ آئوٽ پرو استعمال ڪندي ڪارٽ، آرڊر وصول ٿيل ۽ آرڊر ڏسو صفحن تي پڻ لاڳو ٿي سگهي ٿو.','Action link on the order summary at checkout.' => 'چيڪ آئوٽ تي آرڊر جي خلاصي تي عمل جو لنڪ.','Edit cart link' => 'ڪارٽ لنڪ ايڊٽ ڪريو','Cart items count' => 'ڪارٽ جي شين جو تعداد','Link to shop page' => 'دڪان جي صفحي جو لنڪ','Cart items' => 'ڪارٽ جون شيون','Hide cart items errors at the checkout page' => 'چيڪ آئوٽ صفحي تي ڪارٽ آئٽمز جون غلطيون لڪايو','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'چيڪ آئوٽ صفحي جي چوٽي تي ڪارٽ آئٽمز جي غلطين جو پيغام نه ڏيکاريو. خريداري مڪمل ڪرڻ لاءِ چيڪ آئوٽ فارم جمع ڪرائڻ وقت، اهي غلطي جا پيغام هميشه ڏيکاريا ويندا.','Place order' => 'آرڊر ڏيو','Define the position to display "Place order" and terms checkbox section.' => '&quot;آرڊر ڏيو&quot; ۽ اصطلاحن جي چيڪ باڪس سيڪشن کي ڏيکارڻ لاءِ پوزيشن بيان ڪريو.','Some options might not be compatible with some plugins and themes.' => 'ڪجھ آپشن ڪجھ پلگ ان ۽ ٿيمز سان مطابقت نه رکندا.','Below the payment section' => 'ادائيگي سيڪشن هيٺ','Below the order summary' => 'آرڊر جي خلاصي هيٺ','Both below the payment section and the order summary' => 'ادائيگي واري حصي جي هيٺان ۽ آرڊر جو خلاصو ٻئي','Add widget areas to the checkout page' => 'چيڪ آئوٽ صفحي تي ويجيٽ ايريا شامل ڪريو','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'اهي ويجيٽ ايريا چيڪ آئوٽ پيج تي اعتماد جي علامتن ۽ اعتماد جي بيجز کي شامل ڪرڻ لاءِ استعمال ڪيا ويندا آهن.','Display the coupon codes section title' => 'ڪوپن ڪوڊ سيڪشن جو عنوان ڏيکاريو','Select position where to display the coupon codes section on the checkout page.' => 'چيڪ آئوٽ صفحي تي ڪوپن ڪوڊ سيڪشن کي ڏيکارڻ لاءِ جڳهه چونڊيو.','Before the checkout steps' => 'چيڪ آئوٽ جي مرحلن کان اڳ','As a substep before payment methods' => 'ادائيگي جي طريقن کان اڳ هڪ ذيلي قدم جي طور تي','As a substep after payment methods' => 'ادائيگي جي طريقن کان پوءِ هڪ متبادل طور تي','Default button style' => 'ڊفالٽ بٽڻ انداز','"Add" link button' => '&quot;شامل ڪريو&quot; لنڪ بٽڻ','Checkout fields' => 'چيڪ آئوٽ فيلڊز','Optional fields' => 'اختياري فيلڊز','Hide optional fields behind a link button' => 'لنڪ بٽڻ جي پويان اختياري فيلڊ لڪايو','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'کليل ان پٽ فيلڊز جي تعداد کي گهٽائڻ لاءِ هن آپشن کي چيڪ رکڻ جي صلاح ڏني وئي آهي، <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">تحقيق پڙهو</a> .','Do not hide "Address line 2" fields behind a link button' => 'لنڪ بٽڻ جي پويان &quot;ايڊريس لائن 2&quot; فيلڊ نه لڪايو.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'صرف تڏهن سفارش ڪئي ويندي آهي جڏهن گھڻن گراهڪن کي اصل ۾ &quot;ايڊريس لائن 2&quot; فيلڊ جي ضرورت هجي، يا جڏهن صحيح شپنگ ايڊريس حاصل ڪرڻ انتهائي اهم هجي (يعني جيڪڏهن کاڌو ۽ ٻيون خراب ٿيندڙ شيون پهچائڻ).','Billing address' => 'بلنگ جو پتو','Select position where to display the billing address section on the checkout page.' => 'چيڪ آئوٽ صفحي تي بلنگ ايڊريس سيڪشن کي ڏيکارڻ لاءِ جڳهه چونڊيو.','As a step before shipping' => 'شپنگ کان اڳ هڪ قدم جي طور تي','As a sub-step before the shipping address section' => 'شپنگ ايڊريس سيڪشن کان اڳ هڪ ذيلي قدم جي طور تي','As a sub-step after the shipping address section' => 'شپنگ ايڊريس سيڪشن کان پوءِ هڪ ذيلي قدم جي طور تي','As a step after shipping' => 'شپنگ کان پوءِ هڪ قدم جي طور تي','As a sub-step before the payment section' => 'ادائيگي جي حصي کان اڳ هڪ ذيلي قدم جي طور تي','Force billing and shipping addresses to the same (single section)' => 'بلنگ ۽ شپنگ ايڊريس کي ساڳئي (هڪ سيڪشن) تي مجبور ڪريو','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;شپنگ/بلنگ ايڊريس جي برابر&quot; لاءِ چيڪ باڪس ڊفالٽ طور تي چيڪ ڪيو ويو آهي','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'جڏهن شپنگ ايڊريس سيڪشن پهرين ڏيکاريو ويندو ته چيڪ باڪس &quot;Same as shiping address&quot; ڊفالٽ طور تي چيڪ ٿيل طور تي شروع ٿيندو.<br> جڏهن بلنگ ايڊريس سيڪشن پهرين ڏيکاريو ويندو ته &quot;بلنگ ايڊريس وانگر&quot; چيڪ باڪس ڊفالٽ طور تي چيڪ ٿيل طور تي شروع ٿيندو.<br> چيڪ آئوٽ تي کليل ان پٽ فيلڊز جي تعداد کي گهٽ ڪرڻ لاءِ، هن آپشن کي چيڪ ٿيل ڇڏڻ جي صلاح ڏني وئي آهي، <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">تحقيق پڙهو</a> .','Highlight the billing address section in the checkout form' => 'چيڪ آئوٽ فارم ۾ بلنگ ايڊريس سيڪشن کي نمايان ڪريو.','Shipping address' => 'پهچائڻ جو پتو','Highlight the shipping address section in the checkout form' => 'چيڪ آئوٽ فارم ۾ شپنگ ايڊريس سيڪشن کي نمايان ڪريو.','Shipping methods' => 'شپنگ جا طريقا','Choose in which position to display the shipping methods section.' => 'شپنگ طريقن جي سيڪشن کي ڪهڙي پوزيشن ۾ ڏيکارڻو آهي چونڊيو.','Before shipping address' => 'پهچائڻ جي پتي کان اڳ','After shipping address' => 'پهچائڻ کان پوءِ جو پتو','Local pickup' => 'مقامي پڪ اپ','Removes shipping address section when a local pickup shipping method is selected.' => 'جڏهن مقامي پڪ اپ شپنگ جو طريقو چونڊيو ويندو آهي ته شپنگ ايڊريس سيڪشن کي هٽائي ٿو.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'جڏهن مقامي پڪ اپ شپنگ جو طريقو چونڊيو ويندو آهي ته شپنگ ايڊريس کي پڪ اپ پوائنٽ جي جڳهه سان تبديل ڪري ٿو.','Choose which address to save as the shipping address for local pickup orders.' => 'مقامي پڪ اپ آرڊر لاءِ شپنگ ايڊريس طور محفوظ ڪرڻ جو پتو چونڊيو.','Save the selected pickup location' => 'چونڊيل پڪ اپ جي جڳھ کي محفوظ ڪريو','Save same as the billing address' => 'بلنگ ايڊريس وانگر ئي محفوظ ڪريو','Do not save any shipping address' => 'ڪو به شپنگ پتو محفوظ نه ڪريو.','Company name field for shipping address' => 'شپنگ ايڊريس لاءِ ڪمپني جو نالو فيلڊ','Change visibility for the company name field for the shipping address section on the checkout form.' => 'چيڪ آئوٽ فارم تي شپنگ ايڊريس سيڪشن لاءِ ڪمپني جي نالي جي فيلڊ جي نمائش تبديل ڪريو.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'جيڪڏهن فيلڊ &quot;اختياري&quot; طور مقرر ڪئي وئي آهي، جيڪا ڊفالٽ نمائش واري حالت آهي، ته پوءِ ڪابه تبديلي لاڳو نه ڪئي ويندي ته جيئن ٻيا پلگ ان ڪنهن به تبديلي کي لاڳو ڪري سگهن جيڪي انهن کي گهربل آهن.','Hidden (remove field)' => 'لڪايو (فيلڊ هٽايو)','Optional' => 'اختياري','Required' => 'گهربل','Add shipping phone field to the checkout form.' => 'چيڪ آئوٽ فارم ۾ شپنگ فون فيلڊ شامل ڪريو.','Choose in which step to display the shipping phone field.' => 'شپنگ فون فيلڊ کي ڪهڙي مرحلي ۾ ڏيکارڻو آهي چونڊيو.','Contact step' => 'رابطي جو قدم','Billing phone' => 'بلنگ فون','Add billing phone field to the checkout form.' => 'چيڪ آئوٽ فارم ۾ بلنگ فون فيلڊ شامل ڪريو.','Choose in which step to display the billing phone field.' => 'بلنگ فون فيلڊ کي ڪهڙي مرحلي ۾ ڏيکارڻو آهي چونڊيو.','Show country code beside the flag' => 'جهنڊي جي ڀرسان ملڪ جو ڪوڊ ڏيکاريو','Show an example of a valid phone number inside phone fields' => 'فون جي خانن اندر هڪ صحيح فون نمبر جو مثال ڏيکاريو.','Do not change placeholders' => 'جڳهه رکندڙ تبديل نه ڪريو','Show if not defined' => 'جيڪڏهن وضاحت نه ڪئي وئي هجي ته ڏيکاريو','Always show' => 'هميشه ڏيکاريو','Order notes' => 'آرڊر نوٽس','Define the visibility of the additional order notes field.' => 'اضافي آرڊر نوٽس فيلڊ جي نمائش جي وضاحت ڪريو.','Gift options' => 'تحفي جا آپشن','Allow customers to add a gift message and other gift related options to the order.' => 'گراهڪن کي آرڊر ۾ تحفي جو پيغام ۽ ٻيا تحفي سان لاڳاپيل آپشن شامل ڪرڻ جي اجازت ڏيو.','Display the gift message as part of the order details table instead of a separate section' => 'تحفي جي پيغام کي الڳ سيڪشن جي بدران آرڊر جي تفصيل جي ٽيبل جي حصي طور ڏيکاريو.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'هي آپشن آرڊر جي تصديق واري صفحي (مهرباني واري صفحي) ۽ اڪائونٽ جي صفحن، اي ميلن ۽ پيڪنگ سلپس تي آرڊر جي تفصيلن کي متاثر ڪري ٿو.','Account matching' => 'اڪائونٽ جي ميچنگ','Enable the account matching feature' => 'اڪائونٽ ميچنگ فيچر کي فعال ڪريو','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'جڏهن ڪو اڪائونٽ اڳ ۾ ئي گراهڪ جي رابطي جي تفصيل سان موجود هجي ته مهمان گراهڪ جي آرڊر کي انهن جي موجوده اڪائونٽ سان ڳنڍيو.','Display message when an account exists with the email address provided' => 'جڏهن ڪو اڪائونٽ موجود هجي ته ڏنل اي ميل پتي سان پيغام ڏيکاريو.','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'اڪائونٽ ٺاهڻ جي شعبن کي نوٽيفڪيشن ۽ لاگ ان ٿيڻ جي آپشن سان تبديل ڪري ٿو. ڪجهه حالتن ۾، گراهڪن جي رازداري جي حفاظت لاءِ هن آپشن کي غير فعال ڇڏڻ جي سفارش ڪئي وڃي ٿي.','Dashboard' => 'ڊيش بورڊ','Integrations' => 'انضمام','License keys' => 'لائسنس جون چاٻيون','Visit our website for more information about our plugins and add-ons.' => 'اسان جي پلگ ان ۽ ايڊ آن بابت وڌيڪ معلومات لاءِ اسان جي ويب سائيٽ جو دورو ڪريو.','Order pay page' => 'آرڊر جي ادائيگي جو صفحو','Order pay' => 'آرڊر جي ادائيگي','Enable order pay page optimizations' => 'آرڊر جي ادائيگي واري صفحي جي اصلاح کي فعال ڪريو','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'گراهڪ کان ادائيگي جي انتظار ۾ موجود موجوده آرڊرن لاءِ آرڊر جي ادائيگي واري صفحي جي ترتيب کي تبديل ڪري ٿو.','Add widget areas to the order pay page' => 'آرڊر جي ادائيگي واري صفحي تي ويجيٽ جا علائقا شامل ڪريو','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'اهي ويجيٽ ايريا آرڊر پي پي پيج تي اعتماد جي علامتن ۽ اعتماد جي بيجز کي شامل ڪرڻ لاءِ استعمال ڪيا ويندا آهن.','Thank you page & order details layout' => 'مهرباني صفحو ۽ آرڊر جي تفصيلن جو لي آئوٽ','Order details optimizations' => 'آرڊر جي تفصيلن جي اصلاح','Enable thank you page and order details optimizations' => 'مهرباني واري صفحي ۽ آرڊر جي تفصيلن جي اصلاح کي فعال ڪريو','Changes the layout of order details on the thank you page and account pages.' => 'مهرباني واري صفحي ۽ اڪائونٽ جي صفحن تي آرڊر جي تفصيلن جي ترتيب کي تبديل ڪري ٿو.','Enable order details customizations on email notifications' => 'اي ميل اطلاعن تي آرڊر تفصيلن جي ڪسٽمائيزيشن کي فعال ڪريو','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'اي ميل اطلاعن تي نوان حصا ڏيکاريو ۽ حصن جي ترتيب تبديل ڪريو. اي ميل اطلاعن تي آرڊر جي تفصيلن جا انداز تبديل نه ٿيندا.','Thank you page' => 'مهرباني جو صفحو','These options affect the thank you page, also known as order received or order confirmation pages.' => 'اهي آپشن شڪرگذاري واري صفحي تي اثر انداز ٿين ٿا، جنهن کي آرڊر وصول ٿيل يا آرڊر جي تصديق واري صفحي جي نالي سان پڻ سڃاتو وڃي ٿو.','Order details layout' => 'آرڊر جي تفصيل جي ترتيب','Display the order details with wide layout on the thank you page' => 'مهرباني واري صفحي تي آرڊر جي تفصيل کي وسيع ترتيب سان ڏيکاريو.','Add widget areas to the thank you page' => 'شڪرگذاري واري صفحي تي ويجيٽ جا علائقا شامل ڪريو','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'اهي ويجيٽ ايريا شڪرگذاري واري صفحي تي اعتماد جي علامتن ۽ اعتماد جي بيجز کي شامل ڪرڻ لاءِ استعمال ڪيا ويندا آهن.','Order actions' => 'آرڊر ڪارناما','Choose in which position to display the order actions.' => 'آرڊر جي عملن کي ڪهڙي پوزيشن ۾ ڏيکارڻو آهي چونڊيو.','Inside the order overview' => 'آرڊر جي جائزو اندر','After the order overview' => 'آرڊر جي جائزو کان پوءِ','After order sections' => 'آرڊر سيڪشن کان پوءِ','Order status' => 'آرڊر جي حيثيت','Display the order status progress bar' => 'آرڊر اسٽيٽس پروگريس بار ڏيکاريو','Choose in which position to display the section.' => 'سيڪشن کي ڪهڙي پوزيشن ۾ ڏيکارڻو آهي چونڊيو.','After the order overview and payment instructions' => 'آرڊر جي جائزو ۽ ادائيگي جي هدايتن کان پوءِ','Before the order items section' => 'آرڊر آئٽمز سيڪشن کان اڳ','Inside the order items section' => 'آرڊر آئٽمز سيڪشن جي اندر','After the order items section' => 'آرڊر آئٽمز سيڪشن کان پوءِ','On the sidebar' => 'سائڊبار تي','Order downloads' => 'آرڊر ڊائون لوڊ ڪريو','Gift message' => 'تحفي جو پيغام','Tools' => 'اوزار','Troubleshooting' => 'مسئلا حل ڪرڻ','Debug options' => 'ڊيبگ آپشنز','Debug mode' => 'ڊيبگ موڊ','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ڊيبگ موڊ استعمال ڪرڻ سان ويب سائيٽ جي ڪارڪردگي متاثر ٿئي ٿي. صرف مسئلو حل ڪرڻ وقت هي آپشن استعمال ڪريو.','Load unminified assets' => 'غير معمولي اثاثا لوڊ ڪريو','Enhanced select fields' => 'بهتر ڪيل چونڊ فيلڊز','Fix automatic zoom-in on form fields' => 'فارم فيلڊز تي خودڪار زوم ان کي درست ڪريو','Set <code>font-size</code> inside form fields to 16px' => 'فارم فيلڊ اندر <code>font-size</code> 16px تي سيٽ ڪريو.','Fluid Checkout' => 'فلوئڊ چيڪ آئوٽ','Settings' => 'سيٽنگون','Support' => 'سپورٽ','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => 'وڌيڪ آپشنز کي کولڻ لاءِ <a target="_blank" href="%s">PRO ۾ اپ گريڊ ڪريو</a> .','(PRO)' => '(پرو)','(experimental)' => '(تجرباتي)','Please verify your phone number.' => 'مھرباني ڪري پنھنجو فون نمبر تصديق ڪريو.','The Bluehost Plugin' => 'بليو هوسٽ پلگ ان','Custom fields' => 'ڪسٽم فيلڊز','Enable custom shipping email field' => 'ڪسٽم شپنگ اي ميل فيلڊ کي فعال ڪريو','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'جڏهن فعال ڪيو ويندو، ته Bluehost پلگ ان مان شپنگ اي ميل فيلڊ چيڪ آئوٽ فارم ۾ شامل ڪيو ويندو.','Captcha Pro by BestWebSoft' => 'بيسٽ ويب سافٽ پاران ڪيپچا پرو','Captcha position' => 'ڪيپچا پوزيشن','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'ڪيپچا سيڪشن ڏيکارڻ لاءِ پوزيشن بيان ڪريو. ڪجھ پوزيشنون چونڊيل ڪيپچا قسم جي لحاظ کان ڪم نه ڪري سگھن ٿيون.','Selecting a pickup point is required before proceeding.' => 'اڳتي وڌڻ کان اڳ پڪ اپ پوائنٽ چونڊڻ ضروري آهي.','Pickup point' => 'پڪ اپ پوائنٽ','Pickup point not selected yet.' => 'پڪ اپ پوائنٽ اڃا تائين منتخب نه ڪيو ويو آهي.','Pickup point:' => 'کڻڻ جو هنڌ:','Mailchimp for WooCommerce' => 'WooCommerce لاءِ ميل چمپ','Subscribe checkbox' => 'سبسڪرائيب چيڪ باڪس','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'چيڪ آئوٽ صفحي تي سبسڪرائب چيڪ باڪس جي پوزيشن کي اوور رائڊ ڪريو ۽ هميشه ان کي رابطي جي قدم تي ڏيکاريو.','Before Shipping Address' => 'موڪلڻ کان اڳ جو پتو','(originally "%s")' => '(اصل ۾ &quot;%s&quot;)','After Shipping Address' => 'شپنگ ايڊريس کان پوءِ','Selecting a collection point is required when shipping with FermoPoint.' => 'فرمو پوائنٽ سان شپنگ ڪرڻ وقت ڪليڪشن پوائنٽ چونڊڻ ضروري آهي.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'جيڪڏهن چيڪ ڪيو وڃي ته اهو استعمال ڪندڙن کي اي ميل ۾ ٽائپس جي غلطين جي اطلاع ڏئي ٿو. (هي خصوصيت بند ڪئي وئي آهي ڇاڪاڻ ته فلوئڊ چيڪ آئوٽ خصوصيت پيش ڪري ٿو. هن آپشن ۾ تبديليون اثر انداز نه ٿينديون)','Enable Mail Check: (disabled feature)' => 'ميل چيڪ کي فعال ڪريو: (غير فعال خصوصيت)','Carrier:' => 'ڪيريئر:','Sendinblue - WooCommerce Email Marketing' => 'سينڊ ان بليو - وو ڪامرس اي ميل مارڪيٽنگ','Sign up checkbox position' => 'سائن اپ چيڪ باڪس جي پوزيشن','Move the sign up checkbox to the contact step' => 'سائن اپ چيڪ باڪس کي رابطي جي مرحلي ڏانهن منتقل ڪريو.','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'جڏهن فعال ڪيو ويندو، ته چيڪ باڪس کي Sendinblue پلگ ان سيٽنگز ۾ بيان ڪيل ڊسپلي جي جڳهه کان آزاد طور تي رابطي جي مرحلي ڏانهن منتقل ڪيو ويندو.','Theme Betheme' => 'ٿيم بيٿم','Checkout progress' => 'چيڪ آئوٽ جي پيش رفت','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'چيڪ آئوٽ، ڪارٽ ۽ آرڊر وصول ٿيل صفحن تي بيٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پٽ ڪريو.','Theme Fennik' => 'ٿيم فينڪ','Breadcrumbs' => 'بريڊ ڪرمبس','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'فلوئڊ چيڪ آئوٽ هيڊر ۽ فوٽر استعمال ڪندي فينڪ ٿيم مان بريڊ ڪرمبس سيڪشن آئوٽ پُٽ ڪريو.','Theme Go' => 'ٿيم گو','My account layout' => 'منهنجي اڪائونٽ جي ترتيب','Enable wide layout on "My account" page.' => '&quot;منهنجو اڪائونٽ&quot; صفحي تي وسيع لي آئوٽ کي فعال ڪريو.','Theme Impreza' => 'ٿيم امپريزا','Header' => 'هيڊر','Spacing for site header at the checkout page (in pixels)' => 'چيڪ آئوٽ صفحي تي سائيٽ هيڊر لاءِ فاصلو (پڪسلز ۾)','Only applicable when using the Impreza theme header at the checkout page.' => 'صرف چيڪ آئوٽ صفحي تي امپريزا ٿيم هيڊر استعمال ڪرڻ وقت لاڳو ٿئي ٿو.','Theme Kapee' => 'ٿيم ڪيپي','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'چيڪ آئوٽ، ڪارٽ ۽ آرڊر وصول ٿيل صفحن تي ڪيپي ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پٽ ڪريو.','Theme Porto' => 'ٿيم پورٽو','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'چيڪ آئوٽ، ڪارٽ ۽ آرڊر وصول ٿيل صفحن تي پورٽو ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پٽ ڪريو.','Theme Pressmart' => 'ٿيم پريس مارٽ','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'پريس مارٽ ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن کي چيڪ آئوٽ، ڪارٽ ۽ آرڊر وصول ٿيل صفحن تي آئوٽ پٽ ڪريو.','Theme The Gem' => 'ٿيم دي گيم','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'فلوئڊ چيڪ آئوٽ هيڊر ۽ فوٽر استعمال ڪندي دي جيم ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پُٽ ڪريو.','Theme Woodmart' => 'ٿيم ووڊ مارٽ','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'فلوئڊ چيڪ آئوٽ هيڊر ۽ فوٽر استعمال ڪندي ووڊ مارٽ ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پُٽ ڪريو.','Checkout options' => 'چيڪ آئوٽ جا آپشن','Disable the theme checkout options' => 'ٿيم چيڪ آئوٽ آپشن کي غير فعال ڪريو','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'ٿيم پاران شامل ڪيل پراڊڪٽ جي تصوير، مقدار جي فيلڊ، هٽائڻ واري بٽڻ ۽ پراڊڪٽ پيج جي لنڪ ڊسپلي آپشن ڊفالٽ طور بند ٿيل آهن.','Theme Atomion' => 'ٿيم ايٽميون','Order progress' => 'آرڊر جي ترقي','Display order progress from the theme' => 'موضوع مان آرڊر جي ترقي ڏيکاريو','Display the form field labels visible on the page' => 'صفحي تي نظر ايندڙ فارم فيلڊ ليبل ڏيکاريو.','It is recommended to keep this option enabled for a better user experience.' => 'بهتر صارف تجربي لاءِ هن آپشن کي فعال رکڻ جي صلاح ڏني وئي آهي.','Theme ZK Nito' => 'ٿيم زي ڪي نيتو','Add extra fields to the checkout form' => 'چيڪ آئوٽ فارم ۾ اضافي فيلڊ شامل ڪريو','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'شپنگ ايڊريس سيڪشن ۾ هڪ اضافي شپنگ اي ميل ۽ شپنگ فون فيلڊ شامل ڪري ٿو.','Go to the home page' => 'هوم پيج تي وڃو','Skip to content' => 'مواد ڏانهن وڃو','Create an account' => 'اڪائونٽ ٺاهيو','Log in to your account' => 'پنهنجي اڪائونٽ ۾ لاگ ان ٿيو','Already have an account?' => 'اڳ ۾ ئي اڪائونٽ آهي؟','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s طور لاگ ان ٿيو. <a href="%2$s">لاگ آئوٽ ٿيو.</a>','Your order has a total amount due of %s. No further payment is needed.' => 'توهان جي آرڊر تي ڪُل رقم %s واجب الادا آهي. وڌيڪ ادائيگي جي ضرورت ناهي.','Close and continue with checkout' => 'بند ڪريو ۽ چيڪ آئوٽ جاري رکو','Continue' => 'جاري رکو','Parcel terminal' => 'پارسل ٽرمينل','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p style=";text-align:right;direction:rtl">هي ويجيٽ فلوئڊ چيڪ آئوٽ سان تبديل ڪيو ويو آهي.</p><p style=";text-align:right;direction:rtl"> فلوئڊ چيڪ آئوٽ استعمال ڪرڻ وقت، چيڪ آئوٽ صفحي کي صحيح طريقي سان ڪم ڪرڻ لاءِ اصل WooCommerce شارٽ ڪوڊ <code>[woocommerce_checkout]</code> استعمال ڪرڻ جي ضرورت آهي.</p><p style=";text-align:right;direction:rtl"> وڌيڪ معلومات لاءِ، فلوئڊ چيڪ آئوٽ دستاويزن جو دورو ڪريو.</p>','Theme The7' => 'ٿيم The7','Additional header sections' => 'اضافي هيڊر سيڪشن','Output additional header sections if enabled in the theme settings.' => 'جيڪڏهن ٿيم سيٽنگز ۾ فعال هجي ته اضافي هيڊر سيڪشن آئوٽ پٽ ڪريو.','More information' => 'وڌيڪ ڄاڻ','Pick a Locker' => 'هڪ لاڪر چونڊيو','Page template' => 'صفحي جو ٽيمپليٽ','Use `Order confirmation` page template for block-based themes' => 'بلاڪ تي ٻڌل موضوعن لاءِ &#39;آرڊر جي تصديق&#39; صفحي جي ٽيمپليٽ استعمال ڪريو.','Only applies when using a block-based theme.' => 'صرف بلاڪ تي ٻڌل موضوع استعمال ڪرڻ وقت لاڳو ٿئي ٿو.','WooCommerce Stripe Gateway' => 'وو ڪامرس اسٽرائپ گيٽ وي','Payment form' => 'ادائيگي فارم','Apply styles to the Stripe payment form fields' => 'اسٽرائپ ادائيگي فارم جي شعبن ۾ انداز لاڳو ڪريو','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'جڏهن فعال ڪيو ويندو، ته فلوئڊ چيڪ آئوٽ پلگ ان سان مطابقت لاءِ بهتر ڪيل اسٽائل لاڳو ڪندو. جيڪڏهن توهان اسٽرائپ ادائيگي فارم فيلڊز لاءِ ڪسٽم اسٽائل استعمال ڪري رهيا آهيو ته توهان شايد هن کي غير فعال ڪرڻ چاهيندا.','Theme Nyture' => 'ٿيم نِچر','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'فلوئڊ چيڪ آئوٽ استعمال ڪندي Nyture ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پُٽ ڪريو.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'گراهڪن کي انهن آرڊرن لاءِ ادائيگي ڪرڻ جي اجازت ڏئي ٿو جيڪي يا ته اسٽور ايڊمن پاران دستي طور تي ٺاهيا ويا آهن يا چيڪ آئوٽ دوران مڪمل نه ٿيا آهن.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'ڪواڊليئرز جو پلگ ان WooCommerce Checkout Manager Fluid Checkout سان مطابقت نٿو رکي.','Company name field for billing address' => 'بلنگ ايڊريس لاءِ ڪمپني جي نالي جي فيلڊ','Change visibility for the company name field for the billing address section on the checkout form.' => 'چيڪ آئوٽ فارم تي بلنگ ايڊريس سيڪشن لاءِ ڪمپني جي نالي جي فيلڊ جي نمائش تبديل ڪريو.','Theme Bookshelf' => 'ٿيم بڪ شيلف','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'فلوئڊ چيڪ آئوٽ استعمال ڪندي بُڪ شيلف ٿيم مان چيڪ آئوٽ اسٽيپس سيڪشن آئوٽ پُٽ ڪريو.','Account password' => 'اڪائونٽ پاسورڊ','An account will be created with the information provided at checkout when completing the order.' => 'آرڊر مڪمل ڪرڻ وقت چيڪ آئوٽ تي ڏنل معلومات سان هڪ اڪائونٽ ٺاهيو ويندو.','Choose the style of the progress bar.' => 'ترقي واري بار جو انداز چونڊيو.','Bars' => 'بار','Theme Ireca' => 'ٿيم آئيريڪا','WooCommerce page layout' => 'WooCommerce صفحي جو لي آئوٽ','Force wide layout on WooCommerce pages' => 'WooCommerce صفحن تي وسيع لي آئوٽ کي زور ڏيو','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'هي يقيني بڻائي ٿو ته مواد جو سيڪشن WooCommerce صفحن تي تمام تنگ نه آهي جنهن ۾ چيڪ آئوٽ، ڪارٽ، آرڊر وصول ٿيل، آرڊر جي ادائيگي ۽ اڪائونٽ صفحا شامل آهن.','WooCommerce Smart Coupons' => 'وو ڪامرس سمارٽ ڪوپن','Position on checkout page' => 'چيڪ آئوٽ صفحي تي پوزيشن','Choose where to display the available coupons section on the checkout page.' => 'چيڪ آئوٽ صفحي تي موجود ڪوپن سيڪشن کي ڪٿي ڏيکارڻو آهي چونڊيو.','Before the progress bar' => 'ترقي واري بار کان اڳ','After the progress bar' => 'ترقي واري بار کان پوءِ','Before coupon codes section' => 'ڪوپن ڪوڊ سيڪشن کان اڳ','Format phone numbers according to the rules for each country.' => 'هر ملڪ جي قاعدن مطابق فون نمبر فارميٽ ڪريو.','Use precise phone number validation' => 'صحيح فون نمبر جي تصديق استعمال ڪريو','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'هي هڪ تجرباتي خصوصيت آهي ۽ شايد سڀني سيٽ اپ ۾ توقع مطابق ڪم نه ڪري. ان کي احتياط سان استعمال ڪريو.','Phone number validation types used when precise validation is enabled.' => 'جڏهن صحيح تصديق فعال هجي ته فون نمبر جي تصديق جا قسم استعمال ٿيندا آهن.','Mobile' => 'موبائل','Fixed line' => 'مقرر ٿيل لڪير','Toll free' => 'ٽول فري','Or' => 'يا','Contact' => 'رابطو','Multi step' => 'گھڻا قدم','2 columns' => '2 ڪالم','1 column' => '1 ڪالم','Before checkout steps' => 'چيڪ آئوٽ کان اڳ جا مرحلا','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 ڪالم&quot;</em> چيڪ آئوٽ لي آئوٽ استعمال ڪرڻ وقت هي آپشن هميشه <em>&quot;چڪ آئوٽ مرحلن کان اڳ&quot;</em> تي سيٽ ڪيو ويندو آهي ۽ ڊيسڪ ٽاپ ڏيک تي پڻ لاڳو ٿئي ٿو.','Position for the extra order summary section on mobile.' => 'موبائل تي اضافي آرڊر خلاصو سيڪشن لاءِ پوزيشن.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => '<em>&quot;سائيٽ هيڊر تي&quot;</em> آپشن صرف ان وقت لاڳو ٿئي ٿو جڏهن خلفشار کان پاڪ هيڊر استعمال ڪيو وڃي.','On the site header (requires distraction-free header)' => 'سائيٽ هيڊر تي (بي ڌياني هيڊر جي ضرورت آهي)','Initial state for the expansible order summary section on mobile.' => 'موبائل تي وسعت واري آرڊر خلاصي سيڪشن جي شروعاتي حالت.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'اسان سفارش ڪريون ٿا ته ان کي ريگيوليٽري گهرجن جي ڪري هيٺين ملڪن لاءِ <em>وڌايو وڃي</em> : <strong>جرمني</strong> ، <strong>آسٽريا</strong> ، <strong>سوئٽزرلينڊ</strong> ، <strong>هالينڊ</strong> ، <strong>پولينڊ</strong> ، <strong>بيلجيم</strong> ۽ <strong>فرانس</strong> .','Collapsed' => 'ختم ٿي ويو','Expanded' => 'وڌايو ويو','Do not show' => 'نه ڏيکاريو','yes' => 'ها','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'جيڪڏهن بلنگ ايڊريس سيڪشن شپنگ ايڊريس سيڪشن کان پوءِ ڏيکاريو وڃي ته شپنگ فون فيلڊ کي &quot;لازمي&quot; طور تي مجبور ڪيو وڃي ٿو، ۽ بلنگ فون فيلڊ &quot;لازمي&quot; طور تي سيٽ ڪيو ويو آهي. اهو يقيني بڻائڻ لاءِ ضروري آهي ته شپنگ ايڊريس کي بلنگ ايڊريس تي ڪاپي ڪري سگهجي ٿو جڏهن اهو آپشن چيڪ ڪيو ويندو آهي، ٻي صورت ۾ گراهڪ چيڪ آئوٽ فارم مڪمل ڪرڻ جي قابل نه هوندو.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'جيڪڏهن بلنگ ايڊريس سيڪشن شپنگ ايڊريس سيڪشن کان اڳ ڏيکاريل هجي ته بلنگ فون فيلڊ کي &quot;لازمي&quot; طور تي مجبور ڪيو وڃي ٿو، ۽ شپنگ فون فيلڊ &quot;لازمي&quot; طور تي سيٽ ڪيو ويو آهي. اهو يقيني بڻائڻ لاءِ ضروري آهي ته شپنگ ايڊريس کي بلنگ ايڊريس تي ڪاپي ڪري سگهجي ٿو جڏهن اهو آپشن چيڪ ڪيو ويندو آهي، ٻي صورت ۾ گراهڪ چيڪ آئوٽ فارم مڪمل نه ڪري سگهندو.','Settings profiles' => 'سيٽنگون پروفائلز','Settings profile' => 'سيٽنگون پروفائل','You do not have permission to perform this action.' => 'توهان کي هي عمل ڪرڻ جي اجازت ناهي.','You do not have permission to activate plugins.' => 'توهان کي پلگ ان چالو ڪرڻ جي اجازت ناهي.','Missing plugin.' => 'پلگ ان غائب آهي.','Plugin activated.' => 'پلگ ان چالو ٿيو.','The following changes will be applied:' => 'هيٺيون تبديليون لاڳو ڪيون وينديون:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'فلوئڊ چيڪ آئوٽ 5.0 کان وٺي، سيٽنگون مختلف طريقي سان محفوظ ڪيون ويون آهن. ضرورت پوڻ تي پوئين ورزن ڏانهن ڊائون گريڊ ڪرڻ جي اجازت ڏيڻ لاءِ اڃا تائين ڊيٽابيس ۾ پراڻي آپشن محفوظ ڪيا ويا آهن.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'توهان جو اسٽور نئين سيٽنگن تي تقريباً 2 هفتن کان هلي رهيو آهي تنهنڪري توهان ڊيٽابيس ۾ محفوظ ٿيل پراڻي آپشنز کي صاف ڪري سگهو ٿا. مهرباني ڪري نوٽ ڪريو ته صفائي کان پوءِ، جيڪڏهن توهان کي پلگ ان جي پوئين ورزن تي ڊائون گريڊ ڪرڻ جي ضرورت آهي ته اهو سڀني سيٽنگن لاءِ ڊفالٽ ويليوز استعمال ڪندو.','Fluid Checkout settings cleanup' => 'فلوئڊ چيڪ آئوٽ سيٽنگون صاف ڪرڻ','Delete leftover options' => 'بچيل اختيارن کي ختم ڪريو','Help us improve Fluid Checkout' => 'فلوئڊ چيڪ آئوٽ کي بهتر بڻائڻ ۾ اسان جي مدد ڪريو','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'تيز مدد حاصل ڪرڻ ۽ مطابقت کي بهتر بڻائڻ ۽ اثر کي ماپڻ ۾ اسان جي مدد ڪرڻ لاءِ گمنام سائيٽ ماحول جي رپورٽن کي فلوئڊ چيڪ آئوٽ سان شيئر ڪريو. ڪو به گراهڪ، استعمال ڪندڙ، يا حساس ڊيٽا شامل نه آهي. توهان ڪنهن به وقت ٽولز سيٽنگز مان چونڊي سگهو ٿا ته ڇا شيئر ڪيو وڃي.','Enable site environment reports' => 'سائيٽ جي ماحول جي رپورٽن کي فعال ڪريو','Review settings' => 'سيٽنگن جو جائزو وٺو','This preview has expired. Reload the admin page to start a new preview.' => 'هي ڏيک ختم ٿي چڪو آهي. هڪ نئون ڏيک شروع ڪرڻ لاءِ منتظم صفحي کي ٻيهر لوڊ ڪريو.','Preview expired' => 'ڏيک ختم ٿي ويو','Orders cannot be placed in the preview.' => 'پريويوٽ ۾ آرڊر نه ٿا ڏئي سگهجن.','Logging in is not available in the preview.' => 'پريويو ۾ لاگ ان ٿيڻ موجود ناهي.','Accounts cannot be created in the preview.' => 'پريويو ۾ اڪائونٽس ٺاهي نٿا سگهجن.','Requests to other sites are blocked in the preview.' => 'ٻين سائيٽن ڏانهن درخواستون پريويو ۾ بلاڪ ڪيون ويون آهن.','Processing…' => 'پروسيسنگ…','Something went wrong. Please try again.' => 'ڪجهه غلط ٿيو. مهرباني ڪري ٻيهر ڪوشش ڪريو.','Activate plugin' => 'پلگ ان چالو ڪريو','Fluid Checkout PRO - The complete checkout package' => 'فلوئڊ چيڪ آئوٽ پرو - مڪمل چيڪ آئوٽ پيڪيج','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'سڀ پرو خاصيتون + سڀ ايڊ آن، هڪ قيمت. ڊيزائن ٽيمپليٽ، بهتر ڪيل ڪارٽ ۽ آرڊر حاصل ڪيل صفحا، اڪائونٽ ميچنگ، ۽ گهڻو ڪجهه.','Optimized order pay page' => 'بهتر ڪيل آرڊر جي ادائيگي جو صفحو','Express checkout buttons from supported payment methods' => 'سپورٽ ٿيل ادائيگي جي طريقن مان ايڪسپريس چيڪ آئوٽ بٽڻ','Delayed account creation' => 'اڪائونٽ ٺهڻ ۾ دير','Address autocomplete with Google Maps APIs' => 'گوگل ميپس APIs سان پتو خودڪار طريقي سان مڪمل ٿيو','Multiple saved addresses with the address book' => 'ايڊريس بڪ سان گڏ ڪيترائي محفوظ ٿيل پتا','EU-VAT assistant' => 'EU-VAT اسسٽنٽ','Hide this section' => 'هي حصو لڪايو','Learn more' => 'وڌيڪ سکو','Get early access' => 'جلد رسائي حاصل ڪريو','Activate add-on' => 'ايڊ آن کي فعال ڪريو','Get more out of your checkout journey' => 'پنهنجي چيڪ آئوٽ سفر مان وڌيڪ حاصل ڪريو','Test API key' => 'API ڪي ٽيسٽ ڪريو','Guided setup' => 'هدايت ٿيل سيٽ اپ','Options' => 'اختيارن','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">چيڪ آئوٽ آپشنز</a> تي لي آئوٽ ۽ ڊيزائن سيٽ اپ ڪريو.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'مهمان چيڪ آئوٽ کي فعال ڪريو ۽/يا <a href="%s">گراهڪ اڪائونٽس سيٽنگن جو</a> جائزو وٺو.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'بهتر ڪيل <a href="%1$s">ڪارٽ</a> کي فعال ڪريو، <a href="%2$s">مهرباني ڪريو</a> ۽ <a href="%3$s">ادائيگي جا صفحا آرڊر ڪريو</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'گوگل ميپس مان <a href="%s">ايڊريس آٽو ڪامپليٽ کي</a> فعال ڪريو.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">ايڊريس بڪ</a> سان ڪيترائي محفوظ ڪيل پتا فعال ڪريو.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'چيڪ ڪريو ته ڇا توهان جي نصب ڪيل موضوع يا ٻين پلگ ان لاءِ ڪي <a href="%s">انضمام جا آپشن</a> موجود آهن.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'تيز مدد حاصل ڪريو ۽ مطابقت کي بهتر بڻائڻ ۽ اثر کي ماپڻ ۾ اسان جي مدد ڪريو. اوزارن جي سيٽنگن مان <a href="%s">استعمال جي ٽريڪنگ کي فعال ڪريو</a> .','Missing settings tab.' => 'سيٽنگون ٽيب غائب آهي.','Getting started' => 'شروع ڪرڻ','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>بهترين! توهان جو چيڪ آئوٽ صفحو هاڻي فلوئڊ چيڪ آئوٽ تي هلي رهيو آهي.</strong> شروع ڪرڻ لاءِ هتي ڪجھ قدم آهن:','Completed' => 'مڪمل ٿيو','Preview report data' => 'رپورٽ ڊيٽا جو جائزو وٺو','Send now' => 'هاڻي موڪليو','Auto-detect' => 'خودڪار ڳولا','Afrikaans' => 'آفريڪي','Albanian' => 'الباني','Amharic' => 'امهاري','Arabic' => 'عربي','Armenian' => 'آرمينيائي','Azerbaijani' => 'آذربائيجاني','Basque' => 'بسڪاني','Belarusian' => 'بيلاروسي','Bengali' => 'بنگالي','Bosnian' => 'بوسنيائي','Bulgarian' => 'بلغاريائي','Burmese' => 'برمي','Catalan' => 'قيطلوني','Chinese' => 'چيني','Chinese (Simplified)' => 'چيني (آسان)','Chinese (Hong Kong)' => 'چيني (هانگ ڪانگ)','Chinese (Traditional)' => 'چيني (روايتي)','Croatian' => 'ڪروشيائي','Czech' => 'چيڪ ٻولي','Danish' => 'ڊينش ٻولي','Dutch' => 'ڊچ ٻولي','English' => 'انگريزي','English (Australian)' => 'انگريزي (آسٽريليا)','English (Great Britain)' => 'انگريزي (برطانيه)','Estonian' => 'ايستونائي','Farsi' => 'فارسي','Finnish' => 'فني','Filipino' => 'فلپائني','French' => 'فرانسي','French (Canadian)' => 'فرانسيسي (ڪينيڊين)','Galician' => 'گاليشين ٻولي','Georgian' => 'جيارجي','German' => 'جرمني','Greek' => 'يوناني','Gujarati' => 'گجراتي','Hebrew' => 'عبراني','Hindi' => 'هندي','Hungarian' => 'هنگري','Icelandic' => 'آئس لينڊي','Indonesian' => 'انڊونيشي','Italian' => 'اطالوي','Japanese' => 'جاپاني','Kannada' => 'ڪنادي','Kazakh' => 'قازق','Khmer' => 'خمير','Korean' => 'ڪورين','Kyrgyz' => 'ڪرغيز','Lao' => 'لائو','Latvian' => 'لاتوين ٻولي','Lithuanian' => 'ليٿونيائي','Macedonian' => 'مقدوني','Malay' => 'مالائي','Malayalam' => 'مالايالم','Marathi' => 'مراٺي','Mongolian' => 'منگولي','Nepali' => 'نيپالي','Norwegian' => 'نارويجي','Polish' => 'پالش','Portuguese' => 'پرتگالي','Portuguese (Brazil)' => 'پرتگالي (برازيل)','Portuguese (Portugal)' => 'پرتگالي (پرتگال)','Punjabi' => 'پنجابي','Romanian' => 'رومانوي','Russian' => 'روسي','Serbian' => 'سربيائي','Sinhalese' => 'سنھالي','Slovak' => 'سلوويڪي','Slovenian' => 'سلوويني','Spanish' => 'اندلسي','Spanish (Latin America)' => 'اسپيني (لاطيني آمريڪا)','Swahili' => 'سواهلي','Swedish' => 'سويڊني','Tamil' => 'تاملي','Telugu' => 'تيلوگو ٻولي','Thai' => 'ٿائي ٻولي','Turkish' => 'ترڪي','Ukrainian' => 'يوڪرينيائي','Urdu' => 'اردو','Vietnamese' => 'ويٽنامي','Zulu' => 'زولو','Google address autocomplete' => 'گوگل ايڊريس خودڪار مڪمل','Google Places API version' => 'گوگل جڳهيون API ورزن','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'گوگل پليسز API جو ڪهڙو نسخو استعمال ڪرڻ لاءِ چونڊيو. اسان جلد کان جلد نئين پليسز API ڏانهن منتقل ٿيڻ جي صلاح ڏيون ٿا.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'اسان &quot;Places API (نئون)&quot; استعمال ڪرڻ جي صلاح ڏيون ٿا جيئن 1 مارچ 2025 کان اثرائتو آهي، گوگل &quot;Places API (Legacy)&quot; ورجن کي Legacy اسٽيٽس ۾ منتقل ڪندو، مطلب ته توهان هاڻي هن سروس کي نئين API ڪيز لاءِ فعال نه ڪري سگهندا ۽ API جو اهو ورجن آخرڪار هاڻي دستياب نه هوندو. موجوده اڪائونٽ جيڪي اڳ ۾ ئي Legacy API استعمال ڪري رهيا آهن اهي بغير ڪنهن رڪاوٽ جي ڪم ڪرڻ جاري رکي سگهن ٿا.','(Recommended)' => '(سفارش ٿيل)','Google API key' => 'گوگل API ڪي','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'پنھنجي گوگل API ڪي پيسٽ ڪريو ۽ ٽيسٽ بٽڻ استعمال ڪريو تصديق ڪرڻ لاءِ ته اھو ھن ويب سائيٽ لاءِ ڪم ڪري ٿو. پڪ ڪريو ته ڪي صحيح آھي ۽ توھان جي ڊومين لاءِ اجازت ڏنل آھي، ٻي صورت ۾ ايڊريس فيلڊ بلاڪ ٿي سگھي ٿو جيڪو گراهڪن کي پنھنجا آرڊر مڪمل ڪرڻ کان روڪيندو.','Enable Google address autocomplete' => 'گوگل ايڊريس خودڪار مڪمل ڪرڻ کي فعال ڪريو','Enable address autocompletion using the Google Maps APIs.' => 'گوگل ميپس APIs استعمال ڪندي پتي جي خودڪار مڪمل ٿيڻ کي فعال ڪريو.','Google API language' => 'گوگل API ٻولي','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'هي ٻولي گوگل پليسس API ايڊريس تجويزون ڏيکارڻ لاءِ استعمال ڪئي ويندي ۽ ايڊريس پڻ هن ٻولي ۾ خودڪار طريقي سان مڪمل ڪيا ويندا.','Result types' => 'نتيجن جا قسم','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ڪنهن به قسم جي نتيجن کي قبول ڪرڻ لاءِ خالي ڇڏيو، جيڪو عام طور تي بهتر ملندڙ نتيجا ڏئي ٿو. <a href="%s" target="_blank">وڌيڪ تفصيل لاءِ دستاويز ڏسو</a> .<br> ايڊريس آٽو ڪامپليٽ فيلڊز تي واپس اچڻ لاءِ 5 قسمن جي ايڊريس سرچ نتيجن کي چونڊيو.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">سپورٽ ٿيل قسمن</a> بابت وڌيڪ ڄاڻڻ لاءِ گوگل ميپس دستاويزن جو دورو ڪريو.','Result types (Legacy API)' => 'نتيجن جا قسم (ليگيسي API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (Legacy) استعمال ڪرڻ وقت ڪهڙي قسم جي ايڊريس ڳولا جا نتيجا واپس ڪرڻا آهن.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">سپورٽ ٿيل قسمن</a> بابت وڌيڪ ڄاڻڻ لاءِ Legacy Google Places API جي دستاويزن جو دورو ڪريو.','Company fields' => 'ڪمپني جا شعبا','Enable autocomplete for the company name if available' => 'جيڪڏهن موجود هجي ته ڪمپني جي نالي لاءِ خودڪار مڪمل کي فعال ڪريو.','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'گوگل ميپس APIs مان واپس اچڻ تي ڪمپني جي نالي جي معلومات سان ڪمپني فيلڊ جي خودڪار مڪمل ٿيڻ کي فعال ڪريو.','Business search' => 'ڪاروباري ڳولا','Enable search for businesses in the company field' => 'ڪمپني جي ميدان ۾ ڪاروبار جي ڳولا کي فعال ڪريو','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'ڪمپني جي فيلڊ ۾ ٽائيپ ڪرڻ وقت ڪاروبار سان لاڳاپيل پتن جي تجويز کي فعال ڪريو، پوءِ جڏهن تجويزن مان ڪاروبار چونڊيو وڃي ته سڀني پتن جي فيلڊن کي خودڪار طريقي سان مڪمل ڪريو.','Company result types' => 'ڪمپني جي نتيجن جا قسم','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'خودڪار مڪمل ڪمپني فيلڊز تي واپس اچڻ لاءِ 5 قسمن جي ايڊريس ڳولا جا نتيجا چونڊيو.<br> تجويز ڪيل قدر <code>establishment</code> آهي، جنهن ۾ ڪاروبار جا گهڻا قسم شامل آهن.<br> ڪنهن به قسم جي نتيجن کي قبول ڪرڻ لاءِ خالي ڇڏي ڏيو، جنهن ۾ اهي نتيجا شامل آهن جيڪي ڪاروبار سان لاڳاپيل نه آهن.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">سپورٽ ٿيل قسمن</a> بابت وڌيڪ ڄاڻڻ لاءِ گوگل ميپس دستاويزن جو دورو ڪريو.','Google logo' => 'گوگل لوگو','Show text and logo "Powered by Google"' => '&quot;گوگل پاران طاقتور&quot; متن ۽ لوگو ڏيکاريو.','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'جڏهن چيڪ ڪيو ويندو، ته &quot;گوگل پاران طاقتور&quot; متن ۽ لوگو پتي جي خودڪار مڪمل تجويز واري دٻي جي تري ۾ ڏيکاريو ويندو.','Brasil API address autocomplete' => 'برازيل API پتو خودڪار مڪمل','Brasil API' => 'برازيل API','Enable Brasil API address autocomplete for CEP fields' => 'CEP شعبن لاءِ برازيل API ايڊريس آٽو ڪامپليٽ کي فعال ڪريو','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/پوسٽ ڪوڊ فيلڊ استعمال ڪندي پتي حاصل ڪرڻ ۽ خودڪار طور تي ڀرڻ لاءِ برازيل API استعمال ڪريو. صرف برازيلي پتي لاءِ لاڳاپيل.','API version' => 'API ورزن','Choose which version of the Brasil API CEP method to use.' => 'برازيل API CEP طريقي جو ڪهڙو نسخو استعمال ڪرڻ لاءِ چونڊيو.','Address book migration' => 'ايڊريس بڪ منتقلي','WooCommerce addresses' => 'WooCommerce ايڊريس','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce مان موجوده شپنگ ۽ بلنگ ايڊريس کي گراهڪن جي ايڊريس بڪ ۾ ڪاپي ڪريو.','Enable the address book feature' => 'ايڊريس بڪ جي خصوصيت کي فعال ڪريو','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'گراهڪن کي ڪيترن ئي پتن کي محفوظ ڪرڻ ۽ شپنگ ۽ بلنگ لاءِ استعمال ٿيندڙ ڊفالٽ پتو بيان ڪرڻ جي اجازت ڏيو.','Address labels' => 'ايڊريس ليبلز','Allow customers to add a custom label for each address' => 'گراهڪن کي هر پتي لاءِ هڪ ڪسٽم ليبل شامل ڪرڻ جي اجازت ڏيو.','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'ايڊريس ليبل گراهڪن لاءِ انهن جي محفوظ ڪيل پتن (يعني: &quot;ماءُ جو گهر&quot;) جي وچ ۾ فرق ڪرڻ آسان بڻائين ٿا. ايڊريس ليبل گراهڪن لاءِ خانگي آهن، ۽ آرڊر جي تفصيل واري صفحي يا انوائس تي ڏيکاري يا پرنٽ نه ڪيا ويندا.','Display layout' => 'ڊسپلي لي آئوٽ','Choose how saved addresses are displayed at checkout and on the cart.' => 'چيڪ آئوٽ ۽ ڪارٽ تي محفوظ ڪيل پتا ڪيئن ڏيکاريا وڃن اهو چونڊيو.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'چيڪ آئوٽ ۽ ڪارٽ تي لاڳو ٿئي ٿو. اڪائونٽ صفحي تي محفوظ ڪيل پتا هميشه ڪارڊ لي آئوٽ استعمال ڪندا آهن.','Address cards' => 'ايڊريس ڪارڊ','Address list' => 'پتي جي فهرست','Dropdown field' => 'ڊراپ ڊائون فيلڊ','Address search' => 'پتي جي ڳولا','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'جڏهن گراهڪ وٽ گهٽ ۾ گهٽ هن تعداد ۾ محفوظ ٿيل پتا موجود هجن ته فرنٽ اينڊ تي ايڊريس سرچ فلٽر ڏيکاريو.','Not used when display layout is set to dropdown field.' => 'جڏهن ڊسپلي لي آئوٽ ڊراپ ڊائون فيلڊ تي سيٽ ڪيو ويندو آهي ته استعمال نه ٿيندو آهي.','Addresses' => 'پتا','Enable cart page optimizations to see more options' => 'وڌيڪ آپشن ڏسڻ لاءِ ڪارٽ پيج جي اصلاح کي فعال ڪريو.','Sticky order summary' => 'اسٽڪي آرڊر جو خلاصو','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ڪارٽ پيج تي ڪوپن ڪوڊ سيڪشن کي ڏيکارڻ لاءِ پوزيشن چونڊيو. صرف تڏهن لاڳو ٿئي ٿو جڏهن AJAX ڪارٽ فعال هجي، ۽ جيڪڏهن ڪوپن ڪوڊ جو استعمال WooCommerce سيٽنگز ۾ فعال هجي.','Layout of cross-sell' => 'ڪراس سيل جو لي آئوٽ','Cross-sells displayed' => 'ڪراس سيلز ڏيکاريل آهن','Items' => 'شيون','Cart page optimization' => 'ڪارٽ پيج جي اصلاح','Give your cart the same clear, conversion-focused layout as your checkout.' => 'پنهنجي ڪارٽ کي پنهنجي چيڪ آئوٽ وانگر ساڳيو صاف، تبديلي تي ڌيان ڏيڻ وارو لي آئوٽ ڏيو.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'هڪجهڙائي واري خريداري جي سفر لاءِ ڪارٽ جي ترتيب کي چيڪ آئوٽ صفحي سان ملائي.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'ڪارٽ کي هميشه پس منظر ۾ اپڊيٽ رکو، مقدار تبديل ٿيڻ تي ڪو به پورو صفحو ٻيهر لوڊ نه ٿئي.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'ڪوپن ڪوڊ، شپنگ، ۽ ڪراس سيلز کي بلڪل اتي رکو جتي اهي بهترين طور تي ڪنورٽ ٿين ٿا.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'اسڪرول ڪندي آرڊر جي خلاصي کي نظر ۾ رکو، ۽ جتي خريد ڪندڙن کي يقين ڏيارڻ جي ضرورت هجي اتي اعتماد جا نشان شامل ڪريو.','Columns' => 'ڪالمن','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'چيڪ آئوٽ مرحلن، آرڊر خلاصو ۽ ٻين حصن لاءِ عام انداز. ٻين چيڪ آئوٽ، ڪارٽ، مهرباني (آرڊر ملي ويو)، ۽ آرڊر صفحن کي ڏسڻ تي لاڳو ٿئي ٿو.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'جڏهن <em>&quot;1 ڪالم&quot;</em> لي آئوٽ کي <em>&quot;اسپلٽ&quot;</em> ڊيزائن ٽيمپليٽ سان استعمال ڪيو ويندو آهي، ته هڪ ساڄي ڪالم صرف تڏهن ڏيکاريو ويندو آهي جڏهن صفحي جي سائڊبار ويجيٽ جو علائقو فعال هجي (چيڪ آئوٽ سائڊبار، ڪارٽ سائڊبار، يا آرڊر وصول ٿيل سائڊبار). ٻي صورت ۾ صفحو اسپلٽ اسٽائل سان هڪ واحد ڪالم جي طور تي رهندو.','Split column background' => 'ڪالمن جي پس منظر کي ورهايو','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'اسپلٽ ڊيزائن سيڪنڊري ڪالم لاءِ پس منظر جو رنگ چونڊيو. آرڊر خلاصو پس منظر جو رنگ استعمال ڪرڻ لاءِ خالي ڇڏيو.','Page templates' => 'صفحي جا ٽيمپليٽ','Checkout template' => 'چيڪ آئوٽ ٽيمپليٽ','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'چيڪ آئوٽ تي گهٽ پريشانين لاءِ سفارش ڪئي وئي آهي. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">ڪارٽ ڇڏڻ بابت تحقيق پڙهو</a> .','Sticky progress bar' => 'چپچپا ترقي بار','Progress bar style' => 'ترقي بار انداز','Order totals' => 'آرڊر جو ڪُل تعداد','Background color' => 'پس منظر جو رنگ','Action link' => 'عمل جو لنڪ','Mobile order summary' => 'موبائل آرڊر جو خلاصو','Mobile initial state' => 'موبائل جي شروعاتي حالت','Enable editing cart items at checkout' => 'چيڪ آئوٽ تي ڪارٽ جي شين جي ايڊيٽنگ کي فعال ڪريو','Allow customers to change product quantities or remove items directly at the checkout page.' => 'گراهڪن کي اجازت ڏيو ته اهي پراڊڪٽ جي مقدار تبديل ڪن يا شيون سڌو سنئون چيڪ آئوٽ صفحي تي هٽائي سگهن.','Cart item errors' => 'ڪارٽ جي شين جون غلطيون','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'صرف تڏهن لاڳو ٿئي ٿو جڏهن ڪوپن ڪوڊ چيڪ آئوٽ يا ڪارٽ صفحن تي هڪ الڳ سيڪشن طور ڏيکاريو وڃي، ۽ جيڪڏهن ڪوپن ڪوڊ جو استعمال WooCommerce سيٽنگن ۾ فعال هجي.','Coupon codes position' => 'ڪوپن ڪوڊ جي پوزيشن','Apply coupon button' => 'ڪوپن بٽڻ لاڳو ڪريو','Select style of the "apply coupon" button.' => '&quot;ڪوپن لاڳو ڪريو&quot; بٽڻ جو انداز چونڊيو.','Address line 2' => 'پتو لائن 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'هي سيٽنگ چيڪ آئوٽ ۽ مقامي پڪ اپ سيڪشن جي وچ ۾ شيئر ڪئي وئي آهي. مقامي پڪ اپ سيڪشن تي، اهو اهو پڻ فيصلو ڪري ٿو ته ڇا شپ/پڪ اپ چونڊيندڙ شپنگ طريقو سيڪشن اندر (پتي کان اڳ) يا هڪ الڳ سيڪشن (بعد ۾) طور ڏيکاري ٿو.','Customer accounts' => 'ڪسٽمر اڪائونٽس','Guest checkout' => 'مهمان چيڪ آئوٽ','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'مهمان چيڪ آئوٽ، لاگ ان، ۽ اڪائونٽ ٺاهڻ جا آپشن WooCommerce اڪائونٽس سيٽنگز واري صفحي تان. اهي هتي توهان جي سهولت لاءِ منظم ڪيا ويا آهن، ۽ تنهن ڪري توهان هر سيٽنگ پروفائل لاءِ مختلف قدر استعمال ڪري سگهو ٿا.','Allow customers to checkout without an account' => 'گراهڪن کي اڪائونٽ کان سواءِ چيڪ آئوٽ ڪرڻ جي اجازت ڏيو','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>سفارش ڪئي وئي آهي</strong> ته جيئن گراهڪن کي چيڪ آئوٽ دوران اڪائونٽ ٺاهڻ يا لاگ ان ڪرڻ لاءِ نه چيو وڃي، جيڪو تبادلي جي شرح گهٽائي سگهي ٿو.','When disabled, customers must log in or create an account to complete the purchase.' => 'جڏهن غير فعال هجي، گراهڪن کي خريداري مڪمل ڪرڻ لاءِ لاگ ان ٿيڻ يا اڪائونٽ ٺاهڻ گهرجي.','Login at checkout' => 'چيڪ آئوٽ تي لاگ ان ڪريو','Enable log-in during checkout' => 'چيڪ آئوٽ دوران لاگ ان کي فعال ڪريو','Show a link for returning customers to log in from the checkout page.' => 'واپس ايندڙ گراهڪن کي چيڪ آئوٽ صفحي تان لاگ ان ٿيڻ لاءِ هڪ لنڪ ڏيکاريو.','Account creation' => 'اڪائونٽ ٺاهڻ','Allow customers to create an account during checkout' => 'چيڪ آئوٽ دوران گراهڪن کي اڪائونٽ ٺاهڻ جي اجازت ڏيو','Customers can create an account before placing their order.' => 'گراهڪ آرڊر ڏيڻ کان اڳ هڪ اڪائونٽ ٺاهي سگهن ٿا.','Allow customers to create an account from the My account page' => 'گراهڪن کي منهنجو اڪائونٽ صفحي تان اڪائونٽ ٺاهڻ جي اجازت ڏيو.','Customers can register a new account from the My account page.' => 'گراهڪ منهنجو اڪائونٽ صفحي تان نئون اڪائونٽ رجسٽر ڪري سگهن ٿا.','Username' => 'استعمال ڪندڙ جو نالو','Generate from customer\'s name' => 'گراهڪ جي نالي مان ٺاهيو','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>سفارش ڪئي وئي آهي</strong> ته جيئن گراهڪن کي چيڪ آئوٽ دوران صارف نالو چونڊڻ لاءِ نه چيو وڃي، جيڪو تبادلي جي شرح گهٽائي سگهي ٿو.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'صارف نالو گراهڪ جي نالي مان پيدا ٿئي ٿو، يا جڏهن نالو استعمال نه ٿو ڪري سگهجي ته اي ميل پتي مان.','Password' => 'پاسورڊ','Send password setup link' => 'پاسورڊ سيٽ اپ لنڪ موڪليو','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>سفارش ڪئي وئي آهي</strong> ته جيئن گراهڪن کي چيڪ آئوٽ دوران پاسورڊ سيٽ ڪرڻ لاءِ نه چيو وڃي، جيڪو تبادلي جي شرح گهٽائي سگهي ٿو.','Customers receive an email to create their password securely.' => 'گراهڪن کي محفوظ طريقي سان پنهنجو پاسورڊ ٺاهڻ لاءِ هڪ اي ميل ملي ٿي.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'رجسٽرڊ گراهڪن کي لاگ ان ٿيڻ کان سواءِ چيڪ آئوٽ مڪمل ڪرڻ ڏيو ۽ رابطي جي تفصيل ملائڻ تي آرڊر کي انهن جي موجوده اڪائونٽ سان ڳنڍيو.','Existing account message' => 'موجوده اڪائونٽ پيغام','Let customers create an account after placing their order, from the thank you page.' => 'آرڊر ڏيڻ کان پوءِ گراهڪن کي شڪريو واري صفحي تان اڪائونٽ ٺاهڻ ڏيو.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'جڏهن مهمان چيڪ آئوٽ ۽ اڪائونٽ ميچنگ فعال هوندا آهن ته هن حصي ۾ آپشن موجود هوندا آهن. دير سان اڪائونٽ ٺاهڻ کي ترتيب ڏيڻ لاءِ مٿي ڏنل ٻنهي خاصيتن کي فعال ڪريو.','Enable delayed account creation' => 'دير سان اڪائونٽ ٺاهڻ کي فعال ڪريو','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'جڏهن مهمان چيڪ آئوٽ ۽ اڪائونٽ ميچنگ ٻئي فعال هجن ته دير سان اڪائونٽ ٺاهڻ کي فعال ڪريو.','Section position' => 'سيڪشن پوزيشن','Before customer details section' => 'ڪسٽمر تفصيلن واري حصي کان اڳ','After customer details section' => 'ڪسٽمر تفصيل واري حصي کان پوءِ','Account creation benefits' => 'اڪائونٽ ٺاهڻ جا فائدا','Leaving the field empty will display the default text.' => 'فيلڊ کي خالي ڇڏڻ سان ڊفالٽ ٽيڪسٽ ظاهر ٿيندو.','Inline buttons' => 'ان لائن بٽڻ','Required fields' => 'گهربل خانا','Enable gift message fields at checkout' => 'چيڪ آئوٽ تي گفٽ ميسيج فيلڊز کي فعال ڪريو','Expanded gift message' => 'وڌايل تحفي جو پيغام','Display gift message field always expanded' => 'تحفي جي پيغام جي فيلڊ کي هميشه وڌايو ويو ڏيکاريو','Gift message in order details' => 'آرڊر جي تفصيل ۾ تحفي جو پيغام','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'هن سيڪشن تي هن وقت ڪوبه انضمام موجود ناهي. هر پلگ ان ۽ ٿيم سان لاڳاپيل آپشن صرف هتي ظاهر ٿيندا جڏهن اهو پلگ ان يا ٿيم چالو ڪيو ويندو.','Phone fields' => 'فون جا ميدان','Field visibility' => 'فيلڊ جي نمائش','Field position' => 'فيلڊ پوزيشن','Phone country code & validation' => 'فون ملڪ جو ڪوڊ ۽ تصديق','Country' => 'ملڪ','Enable country on phone fields' => 'فون فيلڊز تي ملڪ کي فعال ڪريو','Filter countries for shipping or billing' => 'شپنگ يا بلنگ لاءِ ملڪن کي فلٽر ڪريو','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'هر فون فيلڊ تي ملڪ چونڊيندڙ کي انهن ملڪن تائين محدود ڪريو جيڪي توهان جي اسٽور تي شپنگ يا بلنگ جي اجازت ڏنل آهن.','Validation' => 'تصديق','Enable simple validation based on country rules' => 'ملڪ جي قاعدن جي بنياد تي سادي تصديق کي فعال ڪريو.','Checks that the phone number is valid for the selected country, including country code and length.' => 'چيڪ ڪري ٿو ته فون نمبر چونڊيل ملڪ لاءِ صحيح آهي، جنهن ۾ ملڪ جو ڪوڊ ۽ ڊيگهه شامل آهي.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'وڌيڪ سختي سان چيڪ ڪريو ته نمبر هڪ صحيح موبائل، فڪسڊ لائن، يا چونڊيل ملڪ لاءِ ٻيو قبول ٿيل قسم آهي. ڪجهه صحيح نمبر رد ڪري سگهن ٿا.','Validation types' => 'تصديق جا قسم','Placeholders' => 'جڳهه رکندڙ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'هن وقت منظم ڪرڻ لاءِ ڪا به لائسنس ڪيز ناهي. لائسنس ڪيز هتي ظاهر ٿينديون جڏهن لائسنس يافته فلوئڊ چيڪ آئوٽ پلگ ان يا ايڊ آن فعال هوندو.','Default delivery type' => 'ڊفالٽ پهچائڻ جو قسم','Choose which delivery type will be selected by default.' => 'ڊفالٽ طور تي ڪهڙي قسم جي ترسيل چونڊيو ويندو اهو چونڊيو.','Shipping zone fields' => 'شپنگ زون جا ميدان','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'مقامي پڪ اپ شپنگ زون فلٽر فيلڊز لاءِ ڪهڙا فيلڊز ڏيکاريا ويندا چونڊيو. سڀ موجود آپشن ڏيکارڻ لاءِ خالي ڇڏيو.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'اهي فيلڊ مقامي پڪ اپ شپنگ طريقن لاءِ فلٽر طور ڏيکاريا ويندا. ڪجهه فيلڊ اڃا تائين چيڪ آئوٽ تي ظاهر ٿي سگهن ٿا جڏهن هتي نه چونڊيو ويو آهي، جيڪڏهن مطابقت رکندڙ پلگ ان کي انهن کي صحيح طريقي سان ڪم ڪرڻ جي ضرورت آهي.','Order shipping address' => 'آرڊر پهچائڻ جو پتو','Order pay page optimization' => 'آرڊر پي پيج جي اصلاح','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'بغير ادا ڪيل آرڊرن کي چيڪ آئوٽ وانگر ساڳيو واضح، تبديلي تي ڌيان ڏيڻ وارو لي آئوٽ ڏيو.','Optimize the layout of the order pay page for orders pending payment.' => 'آرڊر جي ادائيگي جي انتظار ۾ آرڊرن لاءِ آرڊر جي ادائيگي واري صفحي جي ترتيب کي بهتر بڻايو.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'هڪجهڙائي واري خريداري جي سفر لاءِ آرڊر جي ادائيگي جي تجربي کي پنهنجي چيڪ آئوٽ سان ملائي ڏسو.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'اعتماد جا نشان ۽ بيج شامل ڪريو جتي خريد ڪندڙن کي ادائيگي ڪرڻ کان اڳ يقين ڏيارڻ جي ضرورت هجي.','Thank you page optimization' => 'صفحي جي اصلاح جي مهرباني','Make the thank you page and order details clearer for customers after they buy.' => 'گراهڪن جي خريداري کان پوءِ شڪرگذاري واري صفحي ۽ آرڊر جي تفصيلن کي وڌيڪ واضح ڪريو.','Optimize the thank you page and account order details with a clearer layout.' => 'وڌيڪ واضح ترتيب سان شڪرگذاري واري صفحي ۽ اڪائونٽ آرڊر جي تفصيلن کي بهتر بڻايو.','Show order status progress, actions, downloads, and notes where they make sense.' => 'آرڊر جي حيثيت جي ترقي، ڪارروايون، ڊائون لوڊ، ۽ نوٽس ڏيکاريو جتي اهي سمجهه ۾ اچن.','Customize order details sections on email notifications.' => 'اي ميل اطلاعن تي آرڊر جي تفصيلن جي حصن کي ترتيب ڏيو.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'جتي خريد ڪندڙن کي خريداري کان پوءِ يقين ڏيارڻ جي ضرورت هجي، اتي اعتماد جا نشان ۽ بيج شامل ڪريو.','Email notifications' => 'اي ميل اطلاع','Enable thank you page and order details optimizations to see more options' => 'وڌيڪ آپشن ڏسڻ لاءِ مهرباني واري صفحي ۽ آرڊر جي تفصيل جي اصلاح کي فعال ڪريو.','Use wide layout on thank you page' => 'مهرباني واري صفحي تي وسيع لي آئوٽ استعمال ڪريو','These options affect the thank you page, view order details on account pages and on email notifications.' => 'اهي آپشن شڪرگذاري واري صفحي تي اثر انداز ٿين ٿا، اڪائونٽ جي صفحن تي ۽ اي ميل اطلاعن تي آرڊر جي تفصيل ڏسو.','Save settings' => 'سيٽنگون محفوظ ڪريو','Docs' => 'دستاويز','Cart' => 'گاڏي','Thank you' => 'تنهنجي مهرباني','Address autocomplete' => 'پتو خودڪار مڪمل','Trust badges' => 'اعتماد جا بيج','You do not have permission to save these settings.' => 'توهان کي انهن سيٽنگن کي محفوظ ڪرڻ جي اجازت ناهي.','Invalid save request.' => 'محفوظ ڪرڻ جي غلط درخواست.','Your settings have been saved.' => 'توهان جون سيٽنگون محفوظ ڪيون ويون آهن.','Saving...' => 'محفوظ ڪري رهيو آهي...','Settings could not be saved. Please try again.' => 'سيٽنگون محفوظ نه ٿي سگهيون. مهرباني ڪري ٻيهر ڪوشش ڪريو.','Dismiss notice' => 'نوٽيس رد ڪريو','Open settings menu' => 'سيٽنگون مينيو کوليو','Close settings menu' => 'سيٽنگون مينيو بند ڪريو','Preview' => 'ڏيکاءُ','Expand preview' => 'پريويو وڌايو','Collapse preview' => 'پريويو کوليو','Show header and footer' => 'هيڊر ۽ فوٽر ڏيکاريو','Hide header and footer' => 'هيڊر ۽ فوٽر لڪايو','Page preview' => 'صفحي جو ڏيک','Preview viewport' => 'ويوپورٽ جو جائزو وٺو','Tablet' => 'ٽيبليٽ','Desktop' => 'ڊيسڪ ٽاپ','Preview width' => 'ويڪر جو جائزو وٺو','Decrease width' => 'ويڪر گھٽايو','Preview width in pixels' => 'ويڪر جو جائزو پڪسلز ۾','Increase width' => 'ويڪر وڌايو','Preview as' => 'پريويو طور تي','Guest' => 'مهمان','Logged in' => 'لاگ ان ٿيو','Preview page' => 'صفحي جو ڏيک','Expand preview for a closer look' => 'وڌيڪ ويجھو ڏسڻ لاءِ پريويو وڌايو','Available with %s.' => '%s سان دستياب آهي.','Turn them on' => 'انهن کي چالو ڪريو','Optimizations for this page are turned off. %s to preview the page.' => 'هن صفحي لاءِ اصلاحون بند ڪيون ويون آهن. صفحي جي ڏيک لاءِ %s.','%s preview' => '%s جو ڏيک','Isolated session · nothing is saved' => 'الڳ ٿيل سيشن · ڪجھ به محفوظ نه آهي.','Usage tracking' => 'استعمال جي ٽريڪنگ','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'فلوئڊ چيڪ آئوٽ کي مطابقت بهتر ڪرڻ ۾ مدد لاءِ غير حساس سائيٽ ماحول جون رپورٽون موڪليو. رپورٽون نه موڪليون وينديون جيستائين هيٺ ڏنل اختيارن ۾ فعال نه ڪيو وڃي.','Send usage tracking reports to Fluid Checkout' => 'فلوئڊ چيڪ آئوٽ کي استعمال جي ٽريڪنگ رپورٽون موڪليو','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'اهي رپورٽون اسان کي توهان جي سائيٽ لاءِ مطابقت ۽ سپورٽ کي بهتر بڻائڻ ۾ مدد ڪن ٿيون ۽ فعال ٿيڻ تي هفتيوار موڪليون وينديون آهن.','No customer, admin user, or any other sensitive data is included in the reports.' => 'رپورٽن ۾ ڪو به گراهڪ، ايڊمن استعمال ڪندڙ، يا ڪو ٻيو حساس ڊيٽا شامل نه آهي.','Basic environment info' => 'بنيادي ماحول جي معلومات','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'ورڈپریس، پي ايڇ پي، وو ڪامرس، ٿيم، ۽ پلگ ان لسٽ ڊيٽا. رپورٽنگ فعال ٿيڻ تي هميشه شامل ڪيو ويندو آهي. اسان کي توهان جي سائيٽ ڪهڙي ماحول ۾ هلي رهي آهي اهو سمجهڻ ۾ مدد ڪندو آهي.','Plugin settings' => 'پلگ ان سيٽنگون','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'سپورٽ درخواستن ۾ مدد لاءِ فلوئڊ چيڪ آئوٽ پلگ ان سيٽنگون موڪلي ٿو ۽ اسان کي سمجهڻ ۾ مدد ڪري ٿو ته توهان اسان جا پلگ ان ڪيئن استعمال ڪري رهيا آهيو.','Coming soon' => 'جلد ايندو','Sales metrics' => 'سيلز ميٽرڪس','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'فلوئڊ چيڪ آئوٽ انسٽال ڪرڻ کان اڳ هڪ سال لاءِ اڄ تائين مهيني آرڊر جي ڳڻپ ۽ ڪل سيلز. اسان کي سمجهڻ ۾ مدد ڪري ٿو ته ڇا توهان اسان جي پلگ ان انسٽال ڪرڻ سان وڌيڪ پئسا ڪمائي رهيا آهيو. ڪو به گراهڪ يا صارف ڊيٽا ڪڏهن به نه موڪليو ويندو آهي.','Utilities' => 'عام واھپي جون شيون','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> جي بدران <code>TomSelect</code> ڊراپ ڊائون ڪمپونينٽ استعمال ڪريو.','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'ٽام سليڪٽ هڪ سادو ڊراپ ڊائون چونڊ جزو آهي جيڪو Select2 جي ڀيٽ ۾ غلطين جو گهٽ خطرو آهي، جڏهن ته ساڳي ڪارڪردگي پيش ڪري ٿو.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'هن پلگ ان پاران بهتر ڪيل صفحن تي فارم فيلڊز اندر فونٽ سائيز کي 16px تي سيٽ ڪري ٿو ته جيئن ننڍن ڊوائيسز تي فارم فيلڊز سان لهه وچڙ ڪرڻ وقت خودڪار طريقي سان زوم ٿيڻ کان بچي سگهجي.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'سفاري ۽ ٻيا برائوزر شايد موبائل ڊوائيسز تي خودڪار طريقي سان زوم ان ڪري سگھن ٿا ته جيئن فونٽ جي سائيز 16px کان ننڍي هجڻ تي متن کي پڙهڻ ۾ آساني ٿئي.','Enable script processing tracking on the browser console.' => 'برائوزر ڪنسول تي اسڪرپٽ پروسيسنگ ٽريڪنگ کي فعال ڪريو.','Unminified assets' => 'غير محدود اثاثا','Google Maps scripts' => 'گوگل ميپس اسڪرپٽ','Do not remove duplicate Google Maps scripts' => 'ڊبليڪٽ گوگل ميپس اسڪرپٽ نه هٽايو','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'جڏهن فعال ڪيو ويندو، ته نقل ٿيل گوگل ميپس اسڪرپٽ نه هٽايا ويندا جيڪي غلطيون ۽ ڪارڪردگي جا مسئلا پيدا ڪري سگهن ٿا. صرف مسئلو حل ڪرڻ وقت هي اختيار استعمال ڪريو.','Widget areas' => 'ويجيٽ ايرياز','Last step on mobile' => 'موبائل تي آخري قدم','Display widgets only at last step on mobile' => 'موبائل تي صرف آخري مرحلي تي ويجيٽس ڏيکاريو','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'موبائل ڊوائيسز تي آخري چيڪ آئوٽ قدم ڏسڻ وقت صرف چيڪ آئوٽ ٽرسٽ بيج ويجيٽ ڏيکاريو','Standard' => 'معياري','VAT number field' => 'VAT نمبر جي فيلڊ','Add a VAT number field to the billing form.' => 'بلنگ فارم ۾ VAT نمبر فيلڊ شامل ڪريو.','Field label' => 'فيلڊ ليبل','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT نمبر فيلڊ (يعني VAT نمبر) جو ليبل سيٽ ڪريو. گھڻ-ٻولي ويب سائيٽن تي، اهو بهتر آهي ته هن فيلڊ کي خالي ڇڏيو وڃي ۽ اصل اسٽرنگ جو ترجمو ڪيو وڃي.','VAT Number' => 'وي اي ٽي نمبر','EU-VAT' => 'يورپي يونين-ويٽ','Enable the VAT number field to see more options' => 'وڌيڪ آپشن ڏسڻ لاءِ VAT نمبر فيلڊ کي فعال ڪريو.','VAT validation' => 'وي اي ٽي جي تصديق','Validate VAT number field for EU-VAT during checkout' => 'چيڪ آئوٽ دوران EU-VAT لاءِ VAT نمبر فيلڊ جي تصديق ڪريو.','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'چيڪ ڪري ٿو ته مهيا ڪيل VAT نمبر يورپي VIES ڊيٽابيس (VAT انفارميشن ايڪسچينج سسٽم) تي رجسٽر ٿيل هڪ صحيح VAT نمبر آهي.','Shop VAT number' => 'دڪان جو VAT نمبر','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'دڪان جو VAT نمبر جيڪو EU-VAT جي تصديق جي درخواست لاءِ استعمال ڪيو ويندو آهي، ۽ انوائس تي ڇپيل هوندو آهي.<br> <strong>اسان توهان جي دڪان VAT نمبر شامل ڪرڻ جي سختي سان صلاح ڏيون ٿا</strong> ڇاڪاڻ ته ٻي صورت ۾ VIES صلاح مشوري جا نتيجا اڪائونٽنگ مقصدن لاءِ صحيح نه هوندا.<br> يعني: <code>ATU99999999</code> يا <code>EE999999999</code> .','Reverse charge' => 'ريورس چارج','Apply reverse charge mechanism' => 'ريورس چارج ميڪانيزم لاڳو ڪريو','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'جڏهن گراهڪ جو VAT نمبر صحيح هجي ته ٽيڪس جي شرح کي صفر تي سيٽ ڪريو ۽ انوائسز تي &quot;ريورس چارج&quot; ڏيکاريو. اسٽور جي ملڪ جي لحاظ کان هڪ مختلف &quot;ريورس چارج&quot; ٽيڪسٽ گهربل ٿي سگهي ٿو.','Same country' => 'ساڳيو ملڪ','Apply reverse charge mechanism for transactions in the shop country:' => 'دڪان جي ملڪ ۾ ٽرانزيڪشن لاءِ ريورس چارج ميڪانيزم لاڳو ڪريو:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'دڪان جي ملڪ ۾ ڪمپنين جي وچ ۾ ٽرانزيڪشن لاءِ ريورس چارج ميڪانيزم لاڳو ڪرڻ کي فعال بڻائي ٿو.','Reverse charge exceptions' => 'ريورس چارج استثنا','Select additional countries to skip applying the reverse charge mechanism.' => 'ريورس چارج ميڪانيزم لاڳو ڪرڻ کان بچڻ لاءِ اضافي ملڪ چونڊيو.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'انهن ملڪن کان آرڊرن تي ٽيڪس وصول ڪيا ويندا جيتوڻيڪ هڪ صحيح VAT نمبر فراهم ڪيو وڃي.','Reverse charge label on invoices' => 'انوائسز تي ريورس چارج ليبل','Set the label of "reverse charge" on the checkout page and order details.' => 'چيڪ آئوٽ صفحي ۽ آرڊر جي تفصيلن تي &quot;ريورس چارج&quot; جو ليبل سيٽ ڪريو.','Reverse charge text on invoices' => 'انوائسز تي ريورس چارج ٽيڪسٽ','Set the label of "reverse charge" text on invoices.' => 'انوائسز تي &quot;ريورس چارج&quot; ٽيڪسٽ جو ليبل سيٽ ڪريو.','Tax to be paid on reverse charge basis' => 'ريورس چارج جي بنياد تي ٽيڪس ادا ڪرڻو پوندو','Company name' => 'ڪمپني جو نالو','Autocomplete company name from VAT number' => 'VAT نمبر مان ڪمپني جو نالو خودڪار طريقي سان مڪمل ڪريو','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'گراهڪ پاران مهيا ڪيل صحيح VAT نمبر جي بنياد تي بلنگ ڪمپني جو نالو ڀريو.','Company name editing' => 'ڪمپني جي نالي جي ايڊيٽنگ','Allow editing of auto-filled company name' => 'خودڪار ڀريل ڪمپني جي نالي جي ايڊيٽنگ جي اجازت ڏيو','When enabled, customers can change the company name associated with the provided VAT number.' => 'جڏهن فعال ڪيو ويندو، گراهڪ مهيا ڪيل VAT نمبر سان لاڳاپيل ڪمپني جو نالو تبديل ڪري سگهن ٿا.','EU-VAT for digital goods' => 'ڊجيٽل سامان لاءِ EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'پهرين جنوري 2015 کان، ڊجيٽل سامان بابت EU VAT ضابطن ۾ تبديليون ڪيون ويون آهن، جيڪي خاص طور تي B2C ٽرانزيڪشن تي اثر انداز ٿين ٿيون. ڊجيٽل سامان تي VAT جو حساب گراهڪ جي مقام جي بنياد تي ڪيو وڃي، ۽ ان جا ثبوت گڏ ڪرڻ جي ضرورت آهي (IP پتو ۽ بلنگ پتو).','Tax classes for digital goods' => 'ڊجيٽل سامان لاءِ ٽيڪس ڪلاس','Select some tax classes' => 'ڪجھ ٽيڪس ڪلاس چونڊيو','Location evidence' => 'جڳھ جو ثبوت','Collect customer\'s location evidence' => 'گراهڪ جي جڳھ جا ثبوت گڏ ڪريو','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP پتو محفوظ ڪري ٿو ۽ ان کي گراهڪ جي بلنگ ايڊريس جي خلاف تصديق ڪري ٿو. جيڪڏهن گراهڪ جي بلنگ ايڊريس ۽ IP مان ملڪ نه ٿو ملي ته انهن کي چيڪ آئوٽ صفحي تي هڪ چيڪ باڪس چيڪ ڪندي پنهنجي بلنگ ايڊريس جي تصديق ڪرڻ گهرجي.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'هي آپشن فلوئڊ چيڪ آئوٽ ۾ منظم ڪيو ويندو آهي. <a href="%s">ان کي ڪسٽمر اڪائونٽس سيٽنگز ۾ تبديل ڪريو</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'هي آپشن فلوئڊ چيڪ آئوٽ ۾ منظم ڪيو ويندو آهي. ان کي فلوئڊ چيڪ آئوٽ &gt; ڪسٽمر اڪائونٽس جي تحت تبديل ڪريو.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'هي آپشن فلوئڊ چيڪ آئوٽ ۾ منظم ڪيو ويندو آهي. جڏهن فلوئڊ چيڪ آئوٽ چالو ڪيو ويندو آهي ته شپنگ منزل هميشه &quot;ڪسٽمر شپنگ ايڊريس تي ڊفالٽ&quot; تي سيٽ ڪئي ويندي آهي. گراهڪ اڃا تائين چيڪ آئوٽ دوران مختلف شپنگ ۽ بلنگ ايڊريس مهيا ڪري سگهن ٿا.<br><br> ڊفالٽ بلنگ ايڊريس کي شپنگ ايڊريس وانگر سيٽ ڪرڻ جو آپشن <a href="%s">فلوئڊ چيڪ آئوٽ سيٽنگز</a> ۾ موجود آهي.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'هي آپشن فلوئڊ چيڪ آئوٽ ۾ منظم ڪيو ويندو آهي. جڏهن فلوئڊ چيڪ آئوٽ چالو ڪيو ويندو آهي ته شپنگ منزل هميشه &quot;ڪسٽمر شپنگ ايڊريس تي ڊفالٽ&quot; تي سيٽ ڪئي ويندي آهي. گراهڪ اڃا تائين چيڪ آئوٽ دوران مختلف شپنگ ۽ بلنگ ايڊريس مهيا ڪري سگهن ٿا.<br><br> ڊفالٽ بلنگ ايڊريس کي شپنگ ايڊريس وانگر سيٽ ڪرڻ جو آپشن WooCommerce &gt; Settings &gt; Fluid Checkout تي موجود آهي.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'اهي سيٽنگون WP ايڊمن &gt; فلوئڊ چيڪ آئوٽ &gt; سيٽنگز ۾ منتقل ڪيون ويون آهن.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'هي WooCommerce سيٽنگون ٽيب ختم ڪيو ويو آهي ۽ فلوئڊ چيڪ آئوٽ 6.0 ۾ هٽايو ويندو.','Go to settings page' => 'سيٽنگون صفحي تي وڃو','Hide this tab permanently' => 'هن ٽيب کي مستقل طور تي لڪايو.','Site report preview' => 'سائيٽ رپورٽ جو ڏيک','This is the data that would be included in the next site environment report based on your current settings.' => 'هي اهو ڊيٽا آهي جيڪو توهان جي موجوده سيٽنگن جي بنياد تي ايندڙ سائيٽ جي ماحول جي رپورٽ ۾ شامل ڪيو ويندو.','Loading report preview...' => 'رپورٽ جو ڏيک لوڊ ٿي رهيو آهي...','Could not load the site report preview. Try again.' => 'سائيٽ رپورٽ جو ڏيک لوڊ نه ٿي سگهيو. ٻيهر ڪوشش ڪريو.','Could not send the site report. Try again.' => 'سائيٽ رپورٽ موڪلي نه سگهيس. ٻيهر ڪوشش ڪريو.','Site report sent successfully.' => 'سائيٽ رپورٽ ڪاميابي سان موڪلي وئي.','Enable and send now' => 'هاڻي فعال ڪريو ۽ موڪليو','Close' => 'بند ڪريو','A site report request is already in progress. Try again in a moment.' => 'سائيٽ جي رپورٽ جي درخواست اڳ ۾ ئي جاري آهي. ٿوري دير ۾ ٻيهر ڪوشش ڪريو.','Site environment reporting is disabled.' => 'سائيٽ جي ماحول جي رپورٽنگ بند ٿيل آهي.','No site report data is available to send.' => 'موڪلڻ لاءِ ڪا به سائيٽ رپورٽ ڊيٽا موجود ناهي.','This site domain cannot send environment reports (local or development domains are excluded).' => 'هي سائيٽ ڊومين ماحولياتي رپورٽون نٿو موڪلي سگهي (مقامي يا ترقي ڊومينز خارج ٿيل آهن).','A site report was sent recently. Try again later.' => 'هڪ سائيٽ رپورٽ تازو موڪلي وئي هئي. بعد ۾ ٻيهر ڪوشش ڪريو.','The site report could not be sent. Try again later.' => 'سائيٽ رپورٽ موڪلي نه سگهي. بعد ۾ ٻيهر ڪوشش ڪريو.','Site environment reporting is not available.' => 'سائيٽ جي ماحول جي رپورٽنگ موجود ناهي.','No site report data is available for the selected settings.' => 'چونڊيل سيٽنگن لاءِ ڪو به سائيٽ رپورٽ ڊيٽا موجود ناهي.','You are not allowed to manage site reports.' => 'توهان کي سائيٽ رپورٽون منظم ڪرڻ جي اجازت ناهي.','PRO feature' => 'پرو خصوصيت','Other plugins' => 'ٻيا پلگ ان','Get only this add-on &mdash; %s' => 'صرف هي اضافو حاصل ڪريو — %s','Install add-on' => 'ايڊ آن انسٽال ڪريو','Upgrade to PRO &mdash; %s' => 'پرو ڏانهن اپ گريڊ ڪريو — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'انهن اختيارن کي ان لاڪ ڪرڻ لاءِ <a target="_blank" href="%1$s">%2$s حاصل ڪريو</a> .','Add-on' => 'ايڊ-آن','View documentation' => 'دستاويز ڏسو','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'درخواستن لاءِ لاگ ان ٿيل ورڈپریس استعمال ڪندڙ جي ضرورت آهي. موجوده استعمال ڪندڙ جي ڊيٽا استعمال ڪرڻ لاءِ user_id کي ڇڏي ڏيو، يا ٻئي اڪائونٽ کي نشانو بڻائڻ لاءِ user_id پاس ڪريو جڏهن ڪال ڪندڙ ان استعمال ڪندڙ کي ايڊٽ ڪري سگهي ٿو (edit_user صلاحيت). غير تصديق ٿيل درخواستون fc_api_forbidden واپس ڪن ٿيون. هڪ غلط استعمال ڪندڙ id fc_api_user_not_found واپس ڪن ٿيون.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 { &quot;ڊيٽا&quot; سان: { ... } } جڏهن هينڊلر هڪ پيل لوڊ واپس ڪري ٿو.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 { &quot;ڪاميابي&quot; سان: سچو } جڏهن ڪو به پيل لوڊ نه هجي (مثال طور DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'ناڪاميون WP_Error (ڪوڊ، پيغام، data.status) مان ورڈپریس REST غلطي JSON واپس ڪن ٿيون. وائر ڪوڊ fc_api_* پريفڪس استعمال ڪن ٿا.','Forbidden access.' => 'منع ٿيل رسائي.','Target user was not found.' => 'ٽارگيٽ استعمال ڪندڙ نه مليو.','This feature is not available.' => 'هي خصوصيت موجود ناهي.','A required address field is missing.' => 'هڪ گهربل پتو خانو غائب آهي.','Postcode or ZIP is invalid.' => 'پوسٽل ڪوڊ يا زپ غلط آهي.','Phone number is invalid.' => 'فون نمبر غلط آهي.','State or county is invalid.' => 'رياست يا ڪائونٽي غلط آهي.','Country is invalid or has no address fields.' => 'ملڪ غلط آهي يا ان ۾ پتي جا ڪي به خانا نه آهن.','The request could not be processed.' => 'درخواست تي عمل نه ٿي سگهيو.','Back to previous step' => 'پوئين مرحلي ڏانهن واپس وڃو','Skip to settings' => 'سيٽنگز ڏانهن وڃو','Start over and return to the first guided setup step' => 'ٻيهر شروع ڪريو ۽ پهرين هدايت واري سيٽ اپ قدم ڏانهن واپس وڃو','Start over' => 'ٻيهر شروع ڪريو','Please complete all sub-steps before continuing.' => 'جاري رکڻ کان اڳ مھرباني ڪري سڀ ذيلي مرحلا مڪمل ڪريو.','Expand' => 'وڌايو','Collapse' => 'ختم ڪريو','Skip' => 'ڇڏي ڏيو','Mark as complete' => 'مڪمل طور تي نشان لڳايو','Mark as incomplete' => 'نامڪمل طور نشان لڳايو','View full-size image: %s' => 'پوري سائيز واري تصوير ڏسو: %s','Full-size setup guide image' => 'مڪمل سائيز سيٽ اپ گائيڊ تصوير','Close image' => 'تصوير بند ڪريو','Fluid Checkout Guided Setup' => 'فلوئڊ چيڪ آئوٽ گائيڊڊ سيٽ اپ','Welcome' => 'ڀلي ڪري آيا','Explore your checkout' => 'پنھنجي چيڪ آئوٽ جي ڳولا ڪريو','All set' => 'سڀ تيار','You do not have permission to access this page.' => 'توهان کي هن صفحي تائين رسائي جي اجازت ناهي.','Go to step %1$d: %2$s' => 'قدم %1$d ڏانهن وڃو: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'هي هدايت ٿيل سيٽ اپ توهان کي فلوئڊ چيڪ آئوٽ سان واقف ٿيڻ ۾ مدد ڪري ٿو. هيٺ ڏنل قدم هاڻي لاءِ جڳهه رکندڙ آهن.','Continue to the next step when you are ready.' => 'جڏهن توهان تيار آهيو ته ايندڙ قدم تي جاري رکو.','Open your store checkout to see Fluid Checkout in action.' => 'فلوئڊ چيڪ آئوٽ کي عمل ۾ ڏسڻ لاءِ پنهنجو اسٽور چيڪ آئوٽ کوليو.','View checkout page' => 'چيڪ آئوٽ صفحو ڏسو','You can return to Fluid Checkout settings to continue configuring your store.' => 'توهان پنهنجي اسٽور کي ترتيب ڏيڻ جاري رکڻ لاءِ فلوئڊ چيڪ آئوٽ سيٽنگز ڏانهن واپس وڃي سگهو ٿا.','Review checkout and cart settings' => 'چيڪ آئوٽ ۽ ڪارٽ سيٽنگن جو جائزو وٺو','Explore add-ons from the dashboard' => 'ڊيش بورڊ مان ايڊ آنز جي ڳولا ڪريو','Finish & go to settings' => 'ختم ڪريو ۽ سيٽنگون ڏانهن وڃو','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ڪنوينشن سان ملائڻ لاءِ ليگيسي ويليو مان بلنگ فون فيلڊ ويزيبلٽي آپشن کي اپڊيٽ ڪريو.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce ڪنوينشن سان ملائڻ لاءِ ليگيسي ويليو مان شپنگ فون فيلڊ ويزيبلٽي آپشن کي اپڊيٽ ڪريو.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'آرڊر سمري پس منظر رنگ جي سيٽنگ کي نئين اسپلٽ ڊيزائن سيڪنڊري ڪالم پس منظر رنگ آپشن ۾ ڪاپي ڪريو.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'بائيٽ شپ پلگ ان استعمال ڪرڻ وقت وڌايل چونڊ فيلڊز جي خاصيت هميشه غير فعال هوندي آهي.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'جرمن مارڪيٽ استعمال ڪرڻ وقت جڳهه آرڊر جي پوزيشن هميشه &quot;آرڊر خلاصي جي هيٺان&quot; تي سيٽ ڪئي ويندي آهي. انهي پلگ ان کي جڳهه آرڊر بٽڻ ۽ قانوني چيڪ بڪس آرڊر خلاصي جي هيٺان ڏيکارڻ جي ضرورت آهي.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce لاءِ جرمنائيزڊ استعمال ڪرڻ وقت جڳهه آرڊر پوزيشن هميشه &quot;آرڊر خلاصي جي هيٺان&quot; تي سيٽ ڪئي ويندي آهي. انهي پلگ ان کي جڳهه آرڊر بٽڻ ۽ قانوني چيڪ بڪس آرڊر خلاصي جي هيٺان ڏيکارڻ جي ضرورت آهي.','Edit pickup locations' => 'پڪ اپ جي جڳهن کي تبديل ڪريو','Use local pickup label from WooCommerce settings' => 'WooCommerce سيٽنگن مان مقامي پڪ اپ ليبل استعمال ڪريو','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'جڏهن فعال ڪيو ويندو آهي، ته چيڪ آئوٽ تي پڪ اپ آپشن ليبل WooCommerce پڪ اپ لوڪيشن سيٽنگز مان عنوان سان ملندو آهي. جڏهن غير فعال ڪيو ويندو آهي، ته ليبل فلوئڊ چيڪ آئوٽ مان ترجمو ٿيندڙ &quot;مقامي پڪ اپ&quot; ٽيڪسٽ استعمال ڪندو آهي.','Button label for applying coupon codesApply' => 'لاڳو ڪريو','Checkout step titleContact' => 'رابطو','Checkout step titleShipping' => 'شپنگ','Checkout step titleBilling' => 'بلنگ','Checkout step titlePayment' => 'ادائگي','Checkout substep change link labelChange' => 'تبديلي','Checkout substep save link labelSave changes' => 'تبديليون محفوظ ڪريو','Substep review textNone.' => 'ڪوبه نه.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'ڪا به تصوير منتخب نه ڪئي وئي آهي.','Settings sectionCart' => 'گاڏي','Settings sectionOrder pay' => 'آرڊر جي ادائيگي','Settings sectionThank you' => 'تنهنجي مهرباني','Settings section titleIntegrations' => 'انضمام','Settings section titleLicense keys' => 'لائسنس جون چاٻيون','Captcha positionBefore place order section' => 'آرڊر ڏيڻ کان اڳ جو سيڪشن','Captcha positionBefore place order button' => 'آرڊر ڏيڻ کان اڳ بٽڻ','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'بند ڪريو','Log in link label at checkout contact stepLog in' => 'لاگ ان','Log in separator label at for when guest checkout is disabledOr continue below' => 'يا هيٺ جاري رکو','Log in separator label at for when guest checkout is disabledOr